function buildShowSponsorAssignmentFormState(sponsor: ShowSponsor): ShowSponsorAssignmentFormState {
  return {
    sponsorId: sponsor.sponsor_id ?? "",
    placementType: sponsor.placement_type ?? "",
    linkedPerformer: sponsor.linked_performer ?? "",
    customNote: sponsor.custom_note ?? "",
    sponsorType: sponsor.sponsor_type ?? sponsor.sponsor?.sponsor_type ?? "",
    defaultContribution:
      sponsor.default_contribution ?? sponsor.sponsor?.default_contribution ?? "",
    estimatedValue:
      sponsor.estimated_value !== null && sponsor.estimated_value !== undefined
        ? formatNumericInputValue(sponsor.estimated_value)
        : sponsor.sponsor?.estimated_value !== null && sponsor.sponsor?.estimated_value !== undefined
          ? formatNumericInputValue(sponsor.sponsor.estimated_value)
          : "",
    recognitionNotes:
      sponsor.recognition_notes ?? sponsor.sponsor?.recognition_notes ?? "",
    compTicketAllowance: String(Math.max(0, sponsor.comp_ticket_allowance ?? 0)),
  };
}

function buildPromoLinkFormState(link: PromoLink): PromoLinkFormState {
  return {
    title: link.title,
    url: link.url,
    linkType: (link.link_type as PromoLinkType | null) ?? "other",
    description: link.description ?? "",
  };
}

function buildSponsorDocumentFormState(sponsor: SponsorLibraryEntry): SponsorDocumentFormState {
  return {
    sponsorshipLevel: sponsor.sponsorship_level ?? "",
    sponsorshipAmount:
      sponsor.sponsorship_amount === null || sponsor.sponsorship_amount === undefined
        ? ""
        : sponsor.sponsorship_amount.toFixed(2),
    paymentStatus: sponsor.payment_status ?? "prospect",
    proposalCoverage: "current-show",
    proposalYear: String(new Date().getFullYear()),
    proposalCustomCoverage: "",
  };
}

function buildPotentialSponsorFormState(
  potentialSponsor: PotentialSponsor,
): PotentialSponsorFormState {
  return {
    businessName: potentialSponsor.business_name,
    contactName: potentialSponsor.contact_name ?? "",
    phone: potentialSponsor.phone ?? "",
    email: potentialSponsor.email ?? "",
    status: potentialSponsor.status,
    notes: potentialSponsor.notes ?? "",
  };
}

function normalizeShowFinanceItem(
  item: Omit<ShowFinanceItem, "amount"> & { amount: number | string | null },
): ShowFinanceItem {
  const parsedAmount =
    typeof item.amount === "number"
      ? item.amount
      : typeof item.amount === "string"
        ? Number.parseFloat(item.amount)
        : 0;

  return {
    ...item,
    amount: Number.isFinite(parsedAmount) ? parsedAmount : 0,
  };
}

function buildFinanceItemFormState(item: ShowFinanceItem): FinanceItemFormState {
  return {
    label: item.label,
    category: item.category ?? "",
    amount: item.amount.toFixed(2),
    notes: item.notes ?? "",
  };
}

function sortFinanceItems(items: ShowFinanceItem[]) {
  return [...items].sort((itemA, itemB) => itemB.created_at.localeCompare(itemA.created_at));
}

function normalizeShowPayoutItem(
  item: Omit<ShowPayoutItem, "amount"> & { amount: number | string | null },
): ShowPayoutItem {
  const parsedAmount =
    typeof item.amount === "number"
      ? item.amount
      : typeof item.amount === "string"
        ? Number.parseFloat(item.amount)
        : 0;

  return {
    ...item,
    amount: Number.isFinite(parsedAmount) ? parsedAmount : 0,
    category: item.category ?? null,
    description: item.description ?? null,
    payment_method: item.payment_method ?? null,
    paid: item.paid ?? false,
  };
}

function buildPayoutFormState(item: ShowPayoutItem): PayoutFormState {
  return {
    payeeName: item.payee_name,
    category: item.category ?? "",
    description: item.description ?? "",
    amount: item.amount.toFixed(2),
    paid: item.paid,
    paymentMethod: item.payment_method ?? "",
  };
}

function sortShowPayoutItems(items: ShowPayoutItem[]) {
  return [...items].sort((itemA, itemB) => itemA.created_at.localeCompare(itemB.created_at));
}

function normalizeGuestListTicketType(value: string | null | undefined): GuestListTicketType {
  return value === "paid_online" || value === "door_paid" || value === "manual" || value === "complimentary"
    ? value
    : "complimentary";
}

function normalizeShowCompTicket(
  item: Omit<ShowCompTicket, "ticket_count" | "checked_in_count"> & {
    ticket_count: number | string | null;
    checked_in_count?: number | string | null;
  },
): ShowCompTicket {
  const parsedTicketCount =
    typeof item.ticket_count === "number"
      ? item.ticket_count
      : typeof item.ticket_count === "string"
        ? Number.parseInt(item.ticket_count, 10)
        : 1;
  const normalizedTicketCount =
    Number.isFinite(parsedTicketCount) && parsedTicketCount > 0 ? parsedTicketCount : 1;
  const parsedCheckedInCount =
    typeof item.checked_in_count === "number"
      ? item.checked_in_count
      : typeof item.checked_in_count === "string"
        ? Number.parseInt(item.checked_in_count, 10)
        : item.checked_in
          ? normalizedTicketCount
          : 0;
  const normalizedCheckedInCount = Math.max(
    0,
    Math.min(
      normalizedTicketCount,
      Number.isFinite(parsedCheckedInCount) ? parsedCheckedInCount : 0,
    ),
  );

  return {
    ...item,
    email: item.email ?? null,
    ticket_count: normalizedTicketCount,
    ticket_type: normalizeGuestListTicketType(item.ticket_type),
    order_id: item.order_id ?? null,
    import_key: item.import_key ?? null,
    notes: item.notes ?? null,
    checked_in: normalizedCheckedInCount >= normalizedTicketCount,
    checked_in_count: normalizedCheckedInCount,
  };
}

function buildCompTicketFormState(item: ShowCompTicket): CompTicketFormState {
  return {
    guestName: item.guest_name,
    email: item.email ?? "",
    ticketCount: String(item.ticket_count),
    ticketType: normalizeGuestListTicketType(item.ticket_type),
    orderId: item.order_id ?? "",
    notes: item.notes ?? "",
    checkedInCount: String(item.checked_in_count),
  };
}

function clampCheckedInCount(value: number, ticketCount: number) {
  return Math.max(0, Math.min(ticketCount, value));
}

function getCompTicketCheckInStatus(item: ShowCompTicket) {
  if (item.checked_in_count <= 0) {
    return {
      label: "Not Checked In",
      className: "bg-amber-200 text-amber-900",
    };
  }

  if (item.checked_in_count >= item.ticket_count) {
    return {
      label: `Fully Checked In: ${item.checked_in_count} of ${item.ticket_count}`,
      className: "bg-emerald-100 text-emerald-800",
    };
  }

  return {
    label: `Partially Checked In: ${item.checked_in_count} of ${item.ticket_count}`,
    className: "bg-sky-100 text-sky-800",
  };
}

function sortShowCompTickets(items: ShowCompTicket[]) {
  return [...items].sort((itemA, itemB) => itemA.created_at.localeCompare(itemB.created_at));
}

function normalizeRehearsalEntry(item: RehearsalEntryRow): RehearsalEntryWithSong {
  const librarySong = Array.isArray(item.library_song)
    ? item.library_song[0] ?? null
    : item.library_song ?? null;
  const customTitle = sanitizeSongTitle(item.custom_title);
  const libraryTitle = sanitizeSongTitle(librarySong?.title);
  const isLibraryLinked = Boolean(item.song_id && libraryTitle);

  return {
    ...item,
    custom_title: item.custom_title ?? null,
    notes: item.notes ?? null,
    sung_by: librarySong?.sung_by ?? item.sung_by ?? null,
    title: customTitle || libraryTitle || "Untitled Song",
    artist: librarySong?.artist ?? librarySong?.sung_by ?? item.sung_by ?? null,
    song_key: librarySong?.song_key ?? librarySong?.key ?? item.key ?? null,
    tempo: librarySong?.tempo ?? null,
    song_type: librarySong?.song_type ?? null,
    is_library_linked: isLibraryLinked,
  };
}

function sortRehearsalEntries(items: RehearsalEntryWithSong[]) {
  const getSectionSortOrder = (sectionLabel: string | null | undefined) => {
    if (sectionLabel === "set1") {
      return 1;
    }

    if (sectionLabel === "set2") {
      return 2;
    }

    return 0;
  };

  return [...items].sort((itemA, itemB) => {
    const sectionDifference =
      getSectionSortOrder(itemA.section_label) - getSectionSortOrder(itemB.section_label);

    if (sectionDifference !== 0) {
      return sectionDifference;
    }

    if (itemA.sort_order !== itemB.sort_order) {
      return itemA.sort_order - itemB.sort_order;
    }

    return itemA.created_at.localeCompare(itemB.created_at);
  });
}

function normalizeRehearsalSectionLabel(value: string | null | undefined): RehearsalSectionLabel {
  if (value === "set1" || value === "set2") {
    return value;
  }

  return "";
}

function formatRehearsalSectionHeading(value: string | null | undefined) {
  if (value === "set1") {
    return "SET 1";
  }

  if (value === "set2") {
    return "SET 2";
  }

  return "";
}

function normalizeRehearsalRecording(item: RehearsalRecording): RehearsalRecording {
  return {
    ...item,
    file_url: item.file_url ?? null,
    rehearsal_entry_id: item.rehearsal_entry_id ?? null,
  };
}

function sortRehearsalRecordings(items: RehearsalRecording[]) {
  return [...items].sort((itemA, itemB) => itemB.created_at.localeCompare(itemA.created_at));
}

type ParsedGuestListImportEntry = {
  guestName: string;
  email: string;
  ticketCount: number;
  ticketType: GuestListTicketType;
  orderId: string;
  notes: string;
  checkedInCount: number;
};

type CompTicketImportPreviewStatus = "new" | "already_imported" | "possible_duplicate";

type CompTicketImportPreviewEntry = ParsedGuestListImportEntry & {
  amountPaid: number;
  importKey: string;
  status: CompTicketImportPreviewStatus;
  matchedTicketId: string | null;
};

type CompTicketImportSource = "website_text" | "square_csv";

function normalizeImportedGuestName(value: string) {
  const trimmedValue = value.trim().replace(/\s+/g, " ");

  if (!trimmedValue) {
    return "";
  }

  if (trimmedValue.includes(",")) {
    const [lastName, firstName] = trimmedValue.split(",").map((part) => part.trim());
    return [firstName, lastName].filter(Boolean).join(" ");
  }

  return trimmedValue;
}

function parseSimpleCsv(text: string) {
  const rows: string[][] = [];
  let currentRow: string[] = [];
  let currentValue = "";
  let inQuotes = false;

  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    const nextCharacter = text[index + 1];

    if (character === "\"") {
      if (inQuotes && nextCharacter === "\"") {
        currentValue += "\"";
        index += 1;
      } else {
        inQuotes = !inQuotes;
      }
      continue;
    }

    if (character === "," && !inQuotes) {
      currentRow.push(currentValue);
      currentValue = "";
      continue;
    }

    if ((character === "\n" || character === "\r") && !inQuotes) {
      if (character === "\r" && nextCharacter === "\n") {
        index += 1;
      }
      currentRow.push(currentValue);
      rows.push(currentRow);
      currentRow = [];
      currentValue = "";
      continue;
    }

    currentValue += character;
  }

  currentRow.push(currentValue);
  rows.push(currentRow);

  return rows
    .map((row) => row.map((value) => value.trim()))
    .filter((row) => row.some((value) => value.length > 0));
}

function normalizeCsvHeader(value: string) {
  return value.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
}

function parseSquareCsvImportText(text: string): ParsedGuestListImportEntry[] {
  const rows = parseSimpleCsv(text);

  if (rows.length < 2) {
    return [];
  }

  const headerRow = rows[0] ?? [];
  const normalizedHeaders = headerRow.map(normalizeCsvHeader);
  const headerIndexLookup = normalizedHeaders.reduce<Record<string, number>>((lookup, header, index) => {
    if (header) {
      lookup[header] = index;
    }
    return lookup;
  }, {});

  const getColumnValue = (row: string[], possibleHeaders: string[]) => {
    for (const header of possibleHeaders) {
      const index = headerIndexLookup[header];
      if (typeof index === "number") {
        return row[index]?.trim() ?? "";
      }
    }
    return "";
  };

  const parseAmount = (value: string) => {
    const normalizedValue = value.replace(/[^0-9.-]+/g, "");
    const parsedValue = Number.parseFloat(normalizedValue);
    return Number.isFinite(parsedValue) ? parsedValue : null;
  };

  return rows
    .slice(1)
    .map((row) => {
      const guestName = normalizeImportedGuestName(
        getColumnValue(row, ["name_recipient", "recipient_name", "customer_name", "order_name", "name"]),
      );
      const email = getColumnValue(
        row,
        ["email_recipient", "recipient_email", "customer_email", "recipient_email_address", "email"],
      );
      const quantityValue = getColumnValue(row, ["quantity_item", "item_quantity", "quantity"]);
      const totalOrderValue = getColumnValue(
        row,
        ["total_order", "order_total", "total", "amount_total", "net_total"],
      );
      const rawOrderId = getColumnValue(row, [
        "order_id",
        "transaction_id",
        "sale_id",
        "payment_id",
      ]);
      const orderId = isLikelyImportedOrderId(rawOrderId)
        ? normalizeImportedOrderId(rawOrderId)
        : "";

      const parsedQuantity = Number.parseInt(quantityValue, 10);
      const parsedTotalOrder = parseAmount(totalOrderValue);
      const fallbackQuantity =
        parsedTotalOrder !== null ? Math.max(1, Math.round(parsedTotalOrder / PAID_ONLINE_TICKET_PRICE)) : 1;
      const ticketCount =
        Number.isFinite(parsedQuantity) && parsedQuantity > 0 ? parsedQuantity : fallbackQuantity;

      if (!guestName && !email) {
        return null;
      }

      return {
        guestName: guestName || email || "Square Customer",
        email,
        ticketCount: Math.max(1, ticketCount),
        ticketType: "paid_online" as GuestListTicketType,
        orderId,
        notes: "",
        checkedInCount: 0,
      };
    })
    .filter((entry): entry is ParsedGuestListImportEntry => Boolean(entry));
}

function normalizeImportedOrderId(value: string) {
  const trimmedValue = value.trim().toUpperCase();

  if (!trimmedValue) {
    return "";
  }

  const splitTicketSuffixMatch = trimmedValue.match(/^(\d{6,})-\d+$/);
  if (splitTicketSuffixMatch) {
    return splitTicketSuffixMatch[1] ?? trimmedValue;
  }

  return trimmedValue;
}

function resolveMcSpecialSegmentPlacementFromSongFlow(
  items: McSponsorPlacementRenderableItem[],
  segmentId: string,
) {
  const segmentIndex = items.findIndex(
    (item) => item.kind === "segment" && item.segment.id === segmentId,
  );

  if (segmentIndex < 0) {
    return {
      placement_type: null,
      anchor_song_id: null,
      anchor_sponsor_read_id: null,
    };
  }

  const immediatePreviousItem = items[segmentIndex - 1];

  if (immediatePreviousItem?.kind === "sponsor") {
    return {
      placement_type: "after_sponsor_read",
      anchor_song_id: null,
      anchor_sponsor_read_id: immediatePreviousItem.sponsor.id,
    };
  }

  if (
    immediatePreviousItem?.kind === "segment" &&
    immediatePreviousItem.segment.placement_type === "after_sponsor_read" &&
    immediatePreviousItem.segment.anchor_sponsor_read_id
  ) {
    return {
      placement_type: "after_sponsor_read",
      anchor_song_id: null,
      anchor_sponsor_read_id: immediatePreviousItem.segment.anchor_sponsor_read_id,
    };
  }

  const previousFixedItem = [...items.slice(0, segmentIndex)]
    .reverse()
    .find((item) => item.kind === "song" || item.kind === "marker");
  const nextFixedItem = items
    .slice(segmentIndex + 1)
    .find((item) => item.kind === "song" || item.kind === "marker");

  if (previousFixedItem) {
    return getMcSpecialSegmentPlacementFromNeighbor(previousFixedItem, "down");
  }

  if (nextFixedItem) {
    return getMcSpecialSegmentPlacementFromNeighbor(nextFixedItem, "up");
  }

  return {
    placement_type: null,
    anchor_song_id: null,
    anchor_sponsor_read_id: null,
  };
}

function getMcSponsorReadDisplayName(sponsor: ShowSponsor) {
  return sponsor.sponsor?.name?.trim() || "Assigned sponsor";
}

function getMcSpecialSegmentPlacementDetails(
  segment: McSpecialSegment,
  placementSponsors: ShowSponsor[],
) {
  if (
    segment.placement_type === "after_sponsor_read" &&
    segment.anchor_sponsor_read_id
  ) {
    const anchorSponsor = placementSponsors.find(
      (sponsor) => sponsor.id === segment.anchor_sponsor_read_id,
    );

    if (anchorSponsor) {
      return `After ${getMcSponsorReadDisplayName(anchorSponsor)} sponsor read`;
    }
  }

  return null;
}

function getMcSpecialSegmentPlacementFromNeighbor(
  neighbor: McSponsorPlacementRenderableItem,
  direction: "up" | "down",
) {
  if (neighbor.kind === "song") {
    return {
      placement_type: direction === "up" ? "before_performer" : "after_performer",
      anchor_song_id: neighbor.song.id,
      anchor_sponsor_read_id: null,
    };
  }

  if (neighbor.kind === "marker") {
    if (neighbor.marker === "before-intermission") {
      return {
        placement_type: "before_intermission",
        anchor_song_id: null,
        anchor_sponsor_read_id: null,
      };
    }

    if (neighbor.marker === "after-intermission") {
      return {
        placement_type: "after_intermission",
        anchor_song_id: null,
        anchor_sponsor_read_id: null,
      };
    }

    if (neighbor.marker === "closing") {
      return {
        placement_type: "closing",
        anchor_song_id: null,
        anchor_sponsor_read_id: null,
      };
    }

    return {
      placement_type: null,
      anchor_song_id: null,
      anchor_sponsor_read_id: null,
    };
  }

  if (neighbor.kind === "segment") {
    return {
      placement_type: neighbor.segment.placement_type ?? null,
      anchor_song_id: neighbor.segment.anchor_song_id ?? null,
      anchor_sponsor_read_id: neighbor.segment.anchor_sponsor_read_id ?? null,
    };
  }

  if (neighbor.kind === "sponsor") {
    return {
      placement_type: direction === "down" ? "after_sponsor_read" : neighbor.sponsor.placement_type ?? null,
      anchor_song_id: direction === "down" ? null : neighbor.sponsor.mc_anchor_song_id ?? null,
      anchor_sponsor_read_id: direction === "down" ? neighbor.sponsor.id : null,
    };
  }

  return {
    placement_type: null,
    anchor_song_id: null,
    anchor_sponsor_read_id: null,
  };
}

function isLikelyImportedOrderId(value: string) {
  const normalizedValue = normalizeImportedOrderId(value);

  if (!normalizedValue) {
    return false;
  }

  if (/\s/.test(normalizedValue)) {
    return false;
  }

  return /[0-9]/.test(normalizedValue);
}

function extractImportedOrderId(value: string) {
  const standaloneOrderIdPattern = /^\d{6,}(?:-\d+)?$/;
  const labelledOrderIdPattern =
    /\b(?:order|transaction)(?:\s*(?:id|number|no\.?))?\s*[:#-]?\s*([A-Z0-9]{6,}(?:-[A-Z0-9]+)*)\b/i;
  const genericOrderIdPattern = /\b([A-Z0-9]{6,}(?:-[A-Z0-9]+)*)\b/i;
  const trimmedValue = value.trim();

  if (!trimmedValue) {
    return "";
  }

  if (standaloneOrderIdPattern.test(trimmedValue)) {
    return normalizeImportedOrderId(trimmedValue);
  }

  const labelledOrderId = trimmedValue.match(labelledOrderIdPattern)?.[1] ?? "";
  if (labelledOrderId) {
    return normalizeImportedOrderId(labelledOrderId);
  }

  const genericOrderId = trimmedValue.match(genericOrderIdPattern)?.[1] ?? "";
  return normalizeImportedOrderId(genericOrderId);
}

function normalizeTicketImportLookupValue(value: string | null | undefined) {
  return value
    ?.trim()
    .toLowerCase()
    .replace(/\s+/g, " ") ?? "";
}

function getPaidOnlineTicketAmount(ticketCount: number) {
  return ticketCount * PAID_ONLINE_TICKET_PRICE;
}

function buildPaidOnlineFallbackImportKey(
  showId: string,
  guestName: string,
  email: string,
  ticketCount: number,
  amountPaid: number,
) {
  return [
    "paid_online",
    showId,
    normalizeTicketImportLookupValue(guestName) || "unknown-buyer",
    normalizeTicketImportLookupValue(email) || "no-email",
    String(ticketCount),
    amountPaid.toFixed(2),
  ].join("::");
}

function buildPaidOnlineOrderImportKey(showId: string, orderId: string) {
  return ["paid_online", showId, "order", normalizeImportedOrderId(orderId)].join("::");
}

function buildPaidOnlineImportPreviewEntry(
  showId: string,
  entry: ParsedGuestListImportEntry,
  existingTickets: ShowCompTicket[],
): CompTicketImportPreviewEntry {
  const amountPaid = getPaidOnlineTicketAmount(entry.ticketCount);
  const fallbackImportKey = buildPaidOnlineFallbackImportKey(
    showId,
    entry.guestName,
    entry.email,
    entry.ticketCount,
    amountPaid,
  );
  const orderImportKey = entry.orderId ? buildPaidOnlineOrderImportKey(showId, entry.orderId) : "";
  const importKey = orderImportKey || fallbackImportKey;
  const normalizedBuyerEmail = normalizeTicketImportLookupValue(entry.email);
  const normalizedBuyerName = normalizeTicketImportLookupValue(entry.guestName);
  const exactMatch = existingTickets.find((ticket) => {
    const existingImportKey = ticket.import_key?.trim() ?? "";
    const existingOrderImportKey = ticket.order_id
      ? buildPaidOnlineOrderImportKey(showId, ticket.order_id)
      : "";
    const canUseFallbackAsImportedMatch = Boolean(existingImportKey || existingOrderImportKey);
    const existingFallbackImportKey = canUseFallbackAsImportedMatch
      ? buildPaidOnlineFallbackImportKey(
          showId,
          ticket.guest_name,
          ticket.email ?? "",
          ticket.ticket_count,
          getPaidOnlineTicketAmount(ticket.ticket_count),
        )
      : "";

    return (
      existingImportKey === importKey ||
      (Boolean(orderImportKey) && existingOrderImportKey === orderImportKey) ||
      (Boolean(existingFallbackImportKey) && existingFallbackImportKey === fallbackImportKey)
    );
  });

  if (exactMatch) {
    return {
      ...entry,
      amountPaid,
      importKey,
      status: "already_imported",
      matchedTicketId: exactMatch.id,
    };
  }

  const possibleDuplicate = existingTickets.find((ticket) => {
    const normalizedExistingEmail = normalizeTicketImportLookupValue(ticket.email);
    const normalizedExistingName = normalizeTicketImportLookupValue(ticket.guest_name);
    const buyerMatches = normalizedBuyerEmail
      ? normalizedExistingEmail === normalizedBuyerEmail
      : Boolean(normalizedBuyerName) && normalizedExistingName === normalizedBuyerName;

    return buyerMatches;
  });

  if (possibleDuplicate) {
    return {
      ...entry,
      amountPaid,
      importKey,
      status: "possible_duplicate",
      matchedTicketId: possibleDuplicate.id,
    };
  }

  return {
    ...entry,
    amountPaid,
    importKey,
    status: "new",
    matchedTicketId: null,
  };
}

function parseGuestListImportText(text: string): ParsedGuestListImportEntry[] {
  const emailPattern = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i;
  const emailBeforeOrderIdPattern = /(\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})(?=(\d{6,}(?:-\d+)?\b))/gi;
  const normalizeGroupingText = (value: string) =>
    value
      .trim()
      .toLowerCase()
      .replace(/\s+/g, " ");
  const normalizedText = text.replace(emailBeforeOrderIdPattern, "$1\n");
  const lines = normalizedText
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  const ticketRecords: Array<{
    baseOrderId: string;
    guestName: string;
    email: string;
    notes: string;
    sourceIndex: number;
  }> = [];

  for (let index = 0; index < lines.length; index += 1) {
    const orderLine = lines[index];
    const baseOrderId = extractImportedOrderId(orderLine);

    if (!baseOrderId) {
      continue;
    }

    const nameLine = lines[index + 1] ?? "";
    const emailLine = lines[index + 2] ?? "";
    const email = emailLine.match(emailPattern)?.[0] ?? "";
    const guestName = normalizeImportedGuestName(nameLine);

    if (!guestName || !email) {
      continue;
    }

    ticketRecords.push({
      baseOrderId,
      guestName,
      email,
      notes: "",
      sourceIndex: index,
    });

    index += 2;
  }

  const groupedEntries = new Map<
    string,
    {
      guestName: string;
      email: string;
      ticketCount: number;
      ticketType: GuestListTicketType;
      orderId: string;
      notes: string;
      checkedInCount: number;
      sourceIndex: number;
    }
  >();

  ticketRecords.forEach((record, index) => {
    const guestName = record.guestName || record.email || `Imported Order ${index + 1}`;
    const email = record.email;
    const baseOrderId = record.baseOrderId;
    const normalizedEmail = normalizeGroupingText(email);
    const normalizedGuestName = normalizeGroupingText(guestName);
    const groupingKey = baseOrderId
      ? `${baseOrderId}::${normalizedEmail || normalizedGuestName || "unknown"}`
      : `${normalizedEmail || normalizedGuestName || `line-${index}`}`;
    const existingEntry = groupedEntries.get(groupingKey);

    if (existingEntry) {
      existingEntry.ticketCount += 1;
      if (!existingEntry.email && email) {
        existingEntry.email = email;
      }
      if (
        (!existingEntry.guestName || existingEntry.guestName.startsWith("Imported Order")) &&
        guestName
      ) {
        existingEntry.guestName = guestName;
      }
      if (baseOrderId && !existingEntry.orderId) {
        existingEntry.orderId = baseOrderId;
      }
      return;
    }

    groupedEntries.set(groupingKey, {
      guestName,
      email,
      ticketCount: 1,
      ticketType: "paid_online",
      orderId: baseOrderId,
      notes: record.notes,
      checkedInCount: 0,
      sourceIndex: record.sourceIndex,
    });
  });

  return [...groupedEntries.values()]
    .sort((entryA, entryB) => entryA.sourceIndex - entryB.sourceIndex)
    .map(({ sourceIndex: _sourceIndex, ...entry }) => entry);
}

function sortShowChecklistItems(items: ShowChecklistItem[]) {
  return [...items].sort((itemA, itemB) => itemA.created_at.localeCompare(itemB.created_at));
}

function getChecklistDueStatus(item: ShowChecklistItem) {
  if (item.completed || !item.due_date) {
    return null;
  }

  const daysUntilDue = getDaysUntilDate(item.due_date);

  if (daysUntilDue === null) {
    return null;
  }

  if (daysUntilDue < 0) {
    return {
      kind: "overdue" as const,
      label: "Overdue",
      className: "bg-rose-100 text-rose-700",
    };
  }

  if (daysUntilDue === 0) {
    return {
      kind: "today" as const,
      label: "Due Today",
      className: "bg-amber-100 text-amber-900",
    };
  }

  if (daysUntilDue <= 2) {
    return {
      kind: "soon" as const,
      label: "Due Soon",
      className: "bg-sky-100 text-sky-800",
    };
  }

  return null;
}

function buildFinanceReportHtml({
  showName,
  showDate,
  venue,
  financeItems,
}: {
  showName: string;
  showDate: string | null;
  venue: string | null;
  financeItems: ShowFinanceItem[];
}) {
  const incomeItems = financeItems.filter((item) => item.type === "income");
  const expenseItems = financeItems.filter((item) => item.type === "expense");
  const totalIncome = incomeItems.reduce((sum, item) => sum + item.amount, 0);
  const totalExpenses = expenseItems.reduce((sum, item) => sum + item.amount, 0);
  const netProfit = totalIncome - totalExpenses;
  const profitMargin = formatProfitMargin(totalIncome, netProfit);

  const buildRows = (items: ShowFinanceItem[]) =>
    items.length === 0
      ? `<tr><td colspan="4" class="empty">No items added.</td></tr>`
      : items
          .map(
            (item) => `
              <tr>
                <td>${escapeHtml(item.label)}</td>
                <td>${escapeHtml(item.category ?? "Uncategorized")}</td>
                <td class="amount">${escapeHtml(formatCurrency(item.amount))}</td>
                <td>${escapeHtml(item.notes ?? "")}</td>
              </tr>
            `,
          )
          .join("");

  return `
    <!doctype html>
    <html lang="en">
      <head>
        <meta charset="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <title>${escapeHtml(`${showName} - Finance Report`)}</title>
        <style>
          :root {
            color-scheme: light;
          }
          body {
            margin: 32px;
            color: #1f2937;
            font-family: Arial, sans-serif;
            background: #ffffff;
          }
          h1, h2, h3, p {
            margin: 0;
          }
          .brand {
            font-size: 12px;
            font-weight: 700;
            letter-spacing: 0.14em;
            text-transform: uppercase;
            color: #047857;
          }
          .header {
            margin-bottom: 24px;
          }
          .header h1 {
            margin-top: 8px;
            font-size: 28px;
          }
          .meta {
            margin-top: 8px;
            display: grid;
            gap: 4px;
            font-size: 14px;
            color: #4b5563;
          }
          .summary {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 12px;
            margin-bottom: 24px;
          }
          .summary-card {
            border: 1px solid #d1d5db;
            border-radius: 12px;
            padding: 12px 14px;
            background: #f9fafb;
          }
          .summary-card p:first-child {
            font-size: 12px;
            font-weight: 700;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            color: #6b7280;
          }
          .summary-card p:last-child {
            margin-top: 6px;
            font-size: 22px;
            font-weight: 700;
          }
          .negative {
            color: #b91c1c;
          }
          .section {
            margin-top: 24px;
          }
          .section h2 {
            margin-bottom: 12px;
            font-size: 20px;
          }
          table {
            width: 100%;
            border-collapse: collapse;
            font-size: 14px;
          }
          th, td {
            padding: 10px 12px;
            border: 1px solid #d1d5db;
            vertical-align: top;
            text-align: left;
          }
          th {
            background: #f3f4f6;
            font-size: 12px;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            color: #4b5563;
          }
          .amount {
            text-align: right;
            white-space: nowrap;
          }
          .totals {
            margin-top: 16px;
            display: grid;
            gap: 6px;
            font-size: 15px;
          }
          .empty {
            text-align: center;
            color: #6b7280;
          }
          @media print {
            body {
              margin: 18px;
            }
            .section {
              break-inside: avoid;
            }
            table, tr, td, th {
              break-inside: avoid;
            }
          }
        </style>
      </head>
      <body>
        <header class="header">
          <p class="brand">Cumberland Mountain Music Show / StageFlow</p>
          <h1>Show Finance Report</h1>
          <div class="meta">
            <p>${escapeHtml(showName)}</p>
            <p>${escapeHtml(formatShowDate(showDate))}</p>
            <p>${escapeHtml(venue?.trim() || "Venue TBD")}</p>
          </div>
        </header>

        <section class="summary">
          <div class="summary-card">
            <p>Total Income</p>
            <p>${escapeHtml(formatCurrency(totalIncome))}</p>
          </div>
          <div class="summary-card">
            <p>Total Expenses</p>
            <p>${escapeHtml(formatCurrency(totalExpenses))}</p>
          </div>
          <div class="summary-card">
            <p>Net Profit / Loss</p>
            <p class="${netProfit < 0 ? "negative" : ""}">${escapeHtml(formatCurrency(netProfit))}</p>
          </div>
          <div class="summary-card">
            <p>Profit Margin</p>
            <p>${escapeHtml(profitMargin ?? "N/A")}</p>
          </div>
        </section>

        <section class="section">
          <h2>Income Breakdown</h2>
          <table>
            <thead>
              <tr>
                <th>Label</th>
                <th>Category</th>
                <th>Amount</th>
                <th>Notes</th>
              </tr>
            </thead>
            <tbody>${buildRows(incomeItems)}</tbody>
          </table>
        </section>

        <section class="section">
          <h2>Expense Breakdown</h2>
          <table>
            <thead>
              <tr>
                <th>Label</th>
                <th>Category</th>
                <th>Amount</th>
                <th>Notes</th>
              </tr>
            </thead>
            <tbody>${buildRows(expenseItems)}</tbody>
          </table>
        </section>

        <section class="section totals">
          <p><strong>Total Income:</strong> ${escapeHtml(formatCurrency(totalIncome))}</p>
          <p><strong>Total Expenses:</strong> ${escapeHtml(formatCurrency(totalExpenses))}</p>
          <p><strong>Net Profit / Loss:</strong> ${escapeHtml(formatCurrency(netProfit))}</p>
          <p><strong>Profit Margin:</strong> ${escapeHtml(profitMargin ?? "N/A")}</p>
        </section>
      </body>
    </html>
  `;
}

