  async function handleAdjustSponsorCompCheckIn(
    sponsor: ShowSponsor,
    delta: number,
    options?: { source?: "single" | "custom"; overrideConfirmed?: boolean },
  ) {
    if (!show) {
      setCompTicketErrorMessage("The show is not loaded yet.");
      return;
    }

    if (delta === 0) {
      return;
    }

    const nextCheckedInCount = Math.max(0, sponsor.comp_tickets_checked_in + delta);
    const exceedsAllowance = nextCheckedInCount > sponsor.comp_ticket_allowance;

    if (exceedsAllowance && !options?.overrideConfirmed) {
      const confirmed = window.confirm(
        `${sponsor.sponsor?.name ?? "This sponsor"} only has ${sponsor.comp_ticket_allowance} comp tickets allowed, but this check-in would bring them to ${nextCheckedInCount}. Continue with an override?`,
      );

      if (!confirmed) {
        return;
      }
    }

    setCompTicketErrorMessage(null);
    setCompTicketStatusMessage(null);
    setActiveSponsorActionId(`sponsor-comp-${sponsor.id}`);

    try {
      const supabase = createClient();
      const { data, error } = await supabase
        .from("show_sponsors")
        .update({
          comp_tickets_checked_in: nextCheckedInCount,
        })
        .eq("id", sponsor.id)
        .eq("show_id", show.id)
        .select("*")
        .single();

      if (error) {
        throw error;
      }

      const normalizedSponsor = attachSponsorToShowAssignment(data as ShowSponsor, sponsorLibrary);

      setShowSponsors((currentSponsors) =>
        currentSponsors.map((currentSponsor) =>
          currentSponsor.id === sponsor.id ? normalizedSponsor : currentSponsor,
        ),
      );
      setSponsorCompCustomAmounts((currentAmounts) => ({
        ...currentAmounts,
        [sponsor.id]: "",
      }));
      setCompTicketStatusMessage(
        `${sponsor.sponsor?.name ?? "Sponsor"} comp check-ins updated to ${nextCheckedInCount}.`,
      );
    } catch (error) {
      setCompTicketErrorMessage(getErrorMessage(error));
    } finally {
      setActiveSponsorActionId(null);
    }
  }



  useEffect(() => {
    if (!show || !isSponsorTicketPrinterOpen) return;
    let cancelled = false;
    const sponsorTicketShowId = show.id;
    const sponsorTicketShowSlug = show.slug;
    const storageKey = `stageflow_sponsor_ticket_template_${sponsorTicketShowId}`;
    async function loadSponsorTicketTemplates() {
      try {
        const response = await fetch(`/api/sponsor-ticket-templates?showId=${encodeURIComponent(sponsorTicketShowId)}&slug=${encodeURIComponent(sponsorTicketShowSlug)}`);
        const payload = (await response.json()) as { success?: boolean; templates?: ShowSponsorTicketTemplate[]; error?: string };
        if (!response.ok || !payload.success) throw new Error(payload.error || "Unable to load saved ticket templates.");
        if (cancelled) return;
        const templates = payload.templates ?? [];
        setSponsorTicketTemplates(templates);
        const sponsorTemplates = templates.filter((template) => template.template_kind !== "general" && template.template_kind !== "general_admission");
        const generalTemplates = templates.filter((template) => template.template_kind === "general");
        const generalAdmissionTemplates = templates.filter((template) => template.template_kind === "general_admission");
        setSelectedSponsorTicketTemplateId((currentId) => {
          if (currentId && sponsorTemplates.some((template) => template.id === currentId)) return currentId;
          const savedId = typeof window !== "undefined" ? window.localStorage.getItem(storageKey) : null;
          if (savedId && sponsorTemplates.some((template) => template.id === savedId)) return savedId;
          return sponsorTemplates[0]?.id ?? "";
        });
        setSelectedGeneralTicketTemplateId((currentId) => {
          if (currentId && generalTemplates.some((template) => template.id === currentId)) return currentId;
          const savedId = typeof window !== "undefined" ? window.localStorage.getItem(`${storageKey}_general`) : null;
          if (savedId && generalTemplates.some((template) => template.id === savedId)) return savedId;
          return generalTemplates[0]?.id ?? "";
        });
        setSelectedGeneralAdmissionTicketTemplateId((currentId) => {
          if (currentId && generalAdmissionTemplates.some((template) => template.id === currentId)) return currentId;
          const savedId = typeof window !== "undefined" ? window.localStorage.getItem(`${storageKey}_ga`) : null;
          if (savedId && generalAdmissionTemplates.some((template) => template.id === savedId)) return savedId;
          return generalAdmissionTemplates[0]?.id ?? "";
        });
      } catch (error) {
        if (!cancelled) setSponsorTicketErrorMessage(getErrorMessage(error));
      }
    }
    void loadSponsorTicketTemplates();
    return () => { cancelled = true; };
  }, [isSponsorTicketPrinterOpen, show]);
  useEffect(() => {
    if (!show || activeTicketWorkflowSection !== "sponsor-comp") {
      return;
    }

    let cancelled = false;
    const sponsorTicketShowId = show.id;

    async function loadSponsorTicketSeats() {
      setSponsorTicketErrorMessage(null);
      try {
        const supabase = createClient();
        const [{ data: links, error: linksError }, { data: assignments, error: assignmentsError }] = await Promise.all([
          supabase
            .from("show_reserved_seating_links")
            .select("*")
            .eq("show_id", sponsorTicketShowId),
          supabase
            .from("show_reserved_seat_assignments")
            .select("*")
            .eq("show_id", sponsorTicketShowId),
        ]);

        if (linksError) throw linksError;
        if (assignmentsError) throw assignmentsError;
        if (cancelled) return;

        const compLinks = ((links ?? []) as ShowReservedSeatingLink[]).filter((link) => link.is_complimentary || link.seat_category === "comp" || link.seat_category === "guest");
        const compAssignments = ((assignments ?? []) as ShowReservedSeatAssignment[]).filter((assignment) => assignment.seat_category === "comp" || assignment.seat_category === "guest");
        setSponsorTicketReservedLinks(compLinks);
        setSponsorTicketReservedAssignments(compAssignments);
      } catch (error) {
        if (!cancelled) setSponsorTicketErrorMessage(getErrorMessage(error));
      }
    }

    void loadSponsorTicketSeats();

    return () => {
      cancelled = true;
    };
  }, [activeTicketWorkflowSection, show, sponsorTicketSeatRefreshKey]);

  const sponsorTicketTemplateOptions = sponsorTicketTemplates.filter((template) => template.template_kind !== "general" && template.template_kind !== "general_admission");
  const generalTicketTemplateOptions = sponsorTicketTemplates.filter((template) => template.template_kind === "general");
  const generalAdmissionTicketTemplateOptions = sponsorTicketTemplates.filter((template) => template.template_kind === "general_admission");
  const selectedSponsorTicketTemplate = sponsorTicketTemplateOptions.find((template) => template.id === selectedSponsorTicketTemplateId) ?? null;
  const selectedGeneralTicketTemplate = generalTicketTemplateOptions.find((template) => template.id === selectedGeneralTicketTemplateId) ?? null;
  const selectedGeneralAdmissionTicketTemplate = generalAdmissionTicketTemplateOptions.find((template) => template.id === selectedGeneralAdmissionTicketTemplateId) ?? null;
  const activeSponsorTicketTemplateUrl = selectedSponsorTicketTemplate?.file_url || sponsorTicketTemplateDataUrl;
  const activeGeneralTicketTemplateUrl = selectedGeneralTicketTemplate?.file_url || generalTicketTemplateDataUrl;
  const activeGeneralAdmissionTicketTemplateUrl = selectedGeneralAdmissionTicketTemplate?.file_url || generalAdmissionTicketTemplateDataUrl;

  useEffect(() => {
    if (!show) return;
    setGeneralAdmissionTicketFormState((currentState) => ({
      ...currentState,
      showEvent: currentState.showEvent || show.name || "Cumberland Mountain Music Show",
      showDate: currentState.showDate || formatShowDate(show.show_date),
      doorsTime: currentState.doorsTime || show.guest_arrival_time || "6:00 PM",
      showTime: currentState.showTime || show.show_start_time || "TBD",
    }));
  }, [show]);
  async function handleSponsorTicketTemplateChange(event: ChangeEvent<HTMLInputElement>, templateKind: "sponsor" | "general" | "general_admission" = "sponsor") {
    const file = event.target.files?.[0];
    setSponsorTicketStatusMessage(null);
    setSponsorTicketErrorMessage(null);

    if (!file) {
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      if (templateKind === "general_admission") setGeneralAdmissionTicketTemplateDataUrl(typeof reader.result === "string" ? reader.result : null);
      else if (templateKind === "general") setGeneralTicketTemplateDataUrl(typeof reader.result === "string" ? reader.result : null);
      else setSponsorTicketTemplateDataUrl(typeof reader.result === "string" ? reader.result : null);
    };
    reader.onerror = () => setSponsorTicketErrorMessage("Could not load the ticket template image.");
    reader.readAsDataURL(file);

    if (!show) {
      return;
    }

    setIsUploadingSponsorTicketTemplate(true);
    try {
      const formData = new FormData();
      formData.append("showId", show.id);
      formData.append("slug", show.slug);
      formData.append("template", file);
      formData.append("templateKind", templateKind);
      const response = await fetch("/api/sponsor-ticket-templates", { method: "POST", body: formData });
      const payload = (await response.json()) as { success?: boolean; template?: ShowSponsorTicketTemplate; error?: string };
      if (!response.ok || !payload.success || !payload.template) throw new Error(payload.error || "Unable to save ticket template.");
      setSponsorTicketTemplates((currentTemplates) => [payload.template!, ...currentTemplates]);
      if (templateKind === "general_admission") {
        setSelectedGeneralAdmissionTicketTemplateId(payload.template.id);
        setGeneralAdmissionTicketTemplateDataUrl(null);
      } else if (templateKind === "general") {
        setSelectedGeneralTicketTemplateId(payload.template.id);
        setGeneralTicketTemplateDataUrl(null);
      } else {
        setSelectedSponsorTicketTemplateId(payload.template.id);
        setSponsorTicketTemplateDataUrl(null);
      }
      const templateStorageSuffix = templateKind === "general_admission" ? "_ga" : templateKind === "general" ? "_general" : "";
      if (typeof window !== "undefined") window.localStorage.setItem(`stageflow_sponsor_ticket_template_${show.id}${templateStorageSuffix}`, payload.template.id);
      setSponsorTicketStatusMessage(templateKind === "general_admission" ? "General Admission ticket template saved and selected." : templateKind === "general" ? "General comp ticket template saved and selected." : "Sponsor ticket template saved and selected.");
    } catch (error) {
      setSponsorTicketErrorMessage(getErrorMessage(error));
    } finally {
      setIsUploadingSponsorTicketTemplate(false);
      event.target.value = "";
    }
  }


  async function handleDeleteSponsorTicketTemplate() {
    const templateToDelete = selectedSponsorTicketTemplate ?? selectedGeneralTicketTemplate ?? selectedGeneralAdmissionTicketTemplate;
    if (!show || !templateToDelete) return;
    const shouldDelete = window.confirm(`Delete ticket template "${templateToDelete.name}"?`);
    if (!shouldDelete) return;
    setActiveSponsorTicketTemplateActionId(templateToDelete.id);
    setSponsorTicketStatusMessage(null);
    setSponsorTicketErrorMessage(null);
    try {
      const response = await fetch("/api/sponsor-ticket-templates", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ slug: show.slug, templateId: templateToDelete.id, filePath: templateToDelete.file_path }),
      });
      const payload = (await response.json()) as { success?: boolean; error?: string };
      if (!response.ok || !payload.success) throw new Error(payload.error || "Unable to delete ticket template.");
      setSponsorTicketTemplates((currentTemplates) => {
        const nextTemplates = currentTemplates.filter((template) => template.id !== templateToDelete.id);
        const sameKindTemplates = nextTemplates.filter((template) => template.template_kind === templateToDelete.template_kind);
        const nextId = sameKindTemplates[0]?.id ?? "";
        if (templateToDelete.template_kind === "general_admission") setSelectedGeneralAdmissionTicketTemplateId(nextId);
        else if (templateToDelete.template_kind === "general") setSelectedGeneralTicketTemplateId(nextId);
        else setSelectedSponsorTicketTemplateId(nextId);
        if (typeof window !== "undefined") {
          const templateStorageSuffix = templateToDelete.template_kind === "general_admission" ? "_ga" : templateToDelete.template_kind === "general" ? "_general" : "";
          const key = `stageflow_sponsor_ticket_template_${show.id}${templateStorageSuffix}`;
          if (nextId) window.localStorage.setItem(key, nextId);
          else window.localStorage.removeItem(key);
        }
        return nextTemplates;
      });
      setSponsorTicketStatusMessage("Ticket template deleted.");
    } catch (error) {
      setSponsorTicketErrorMessage(getErrorMessage(error));
    } finally {
      setActiveSponsorTicketTemplateActionId(null);
    }
  }

  function getSponsorTicketSponsorName(sponsor: ShowSponsor) {
    return sponsor.sponsor?.name ?? sponsor.custom_note?.trim() ?? "Sponsor";
  }

  function getSponsorReservedSeatOptions(sponsor: ShowSponsor) {
    const sponsorName = getSponsorTicketSponsorName(sponsor).trim().toLowerCase();
    const matchedLinks = sponsorTicketReservedLinks.filter((link) =>
      link.customer_name.trim().toLowerCase().includes(sponsorName) ||
      sponsorName.includes(link.customer_name.trim().toLowerCase()),
    );
    const matchedLinkIds = new Set(matchedLinks.map((link) => link.id));
    const assignments = sponsorTicketReservedAssignments.filter((assignment) =>
      assignment.seating_link_id ? matchedLinkIds.has(assignment.seating_link_id) : assignment.customer_name?.trim().toLowerCase().includes(sponsorName),
    );
    const seatIds = sortReservedSeatIds(assignments.map((assignment) => assignment.seat_id));
    return seatIds.map((seatId) => ({ seatId, label: formatReservedSeatLabel(seatId) }));
  }

  function toggleSponsorTicketSeat(seatId: string) {
    setSelectedSponsorTicketSeatIds((currentSeatIds) =>
      currentSeatIds.includes(seatId)
        ? currentSeatIds.filter((currentSeatId) => currentSeatId !== seatId)
        : sortReservedSeatIds([...currentSeatIds, seatId]),
    );
  }

  function handleAssignReservedSeatsFromSponsorTickets() {
    setActiveTicketWorkflowSection("reserved-seating");
    setIsReservedSeatingOpen(true);
    setSponsorTicketErrorMessage(null);
    const sponsor = sponsorsWithCompTickets.find((item) => item.id === sponsorTicketSponsorId) ?? null;
    if (sponsor) {
      setSponsorTicketStatusMessage("Assign comp reserved seats for " + getSponsorTicketSponsorName(sponsor) + ", then return to Ticket Printing.");
    }
    window.setTimeout(() => {
      document.getElementById("reserved-seating-admin-section")?.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 100);
  }

  function handleAssignSeatsForSelectedCompTicketScope() {
    const selectedRows = getCompTicketPrintRows(selectedCompTicketPrintScope as CompTicketPrintScope);
    if (selectedRows.length !== 1) {
      setSponsorTicketErrorMessage("Choose one specific sponsor or comp entry before assigning seats.");
      setSponsorTicketStatusMessage(null);
      setIsSponsorTicketPrinterOpen(true);
      return;
    }
    void handleChangeSeatsForCompRow(selectedRows[0]);
  }

  function startEditingCompEntry(row: CompListReportRow) {
    setEditingCompEntryRowId(row.id);
    setEditingCompEntryFormState({ name: row.name, category: row.category, admissionType: row.admissionType, quantity: String(row.quantity), notes: stripCompMetadataFromNotes(row.notes) });
    setCompTicketErrorMessage(null);
    setCompTicketStatusMessage(null);
  }

  function closeEditingCompEntry() {
    setEditingCompEntryRowId(null);
    setEditingCompEntryFormState({ name: "", category: "guest", admissionType: "reserved", quantity: "1", notes: "" });
  }

  async function handleChangeSeatsForCompRow(row: CompListReportRow) {
    if (!show) return;
    setSelectedCompTicketPrintScope(`row:${row.id}`);
    if (row.id.startsWith("sponsor-")) setSponsorTicketSponsorId(row.id.replace("sponsor-", ""));
    setSponsorTicketErrorMessage(null);

    try {
      const supabase = createClient();
      let linkId: string | null = null;
      if (row.id.startsWith("reserved-comp-")) {
        const assignmentId = row.id.replace("reserved-comp-", "");
        linkId = sponsorTicketReservedAssignments.find((assignment) => assignment.id === assignmentId)?.seating_link_id ?? null;
      }

      if (!linkId) {
        const matchingLink = sponsorTicketReservedLinks.find((link) => {
          const linkName = (link.customer_name ?? "").trim().toLowerCase();
          const rowName = row.name.trim().toLowerCase();
          return linkName === rowName && (link.is_complimentary || link.seat_category === "comp" || link.seat_category === "guest");
        });
        linkId = matchingLink?.id ?? null;
      }

      if (!linkId) {
        const { data, error } = await supabase
          .from("show_reserved_seating_links")
          .insert({
            show_id: show.id,
            customer_name: row.name,
            email: null,
            ticket_count: Math.max(1, row.quantity),
            selection_mode: "comp",
            is_complimentary: true,
            source_note: buildCompCategoryNotes(row.notes, row.category, row.admissionType),
            seat_category: row.category === "guest" ? "guest" : "comp",
          })
          .select("id")
          .single();
        if (error) throw error;
        linkId = data?.id ?? null;
      } else {
        const { error } = await supabase
          .from("show_reserved_seating_links")
          .update({ ticket_count: Math.max(1, row.quantity), customer_name: row.name, source_note: buildCompCategoryNotes(row.notes, row.category, row.admissionType), is_complimentary: true, seat_category: row.category === "guest" ? "guest" : "comp" })
          .eq("id", linkId);
        if (error) throw error;
      }

      if (!linkId) throw new Error("Unable to open reserved seats for this comp entry.");
      setActiveCompSeatAssignment({ row, linkId });
      setActiveTicketWorkflowSection("reserved-seating");
      setIsReservedSeatingOpen(true);
      setSponsorTicketStatusMessage(`Assigning seats for ${row.name}. Select exactly ${Math.max(1, row.quantity)} seat${Math.max(1, row.quantity) === 1 ? "" : "s"}.`);
      setSponsorTicketSeatRefreshKey((currentValue) => currentValue + 1);
      window.setTimeout(() => {
        document.getElementById("reserved-seating-admin-section")?.scrollIntoView({ behavior: "smooth", block: "start" });
      }, 100);
    } catch (error) {
      setSponsorTicketErrorMessage(getErrorMessage(error));
    }
  }

  async function handleSaveCompEntry() {
    if (!show || !editingCompEntryRowId) return;
    const name = editingCompEntryFormState.name.trim();
    const quantity = Number.parseInt(editingCompEntryFormState.quantity.trim(), 10);
    const category = editingCompEntryFormState.category as CompListReportRow["category"];
    const admissionType = editingCompEntryFormState.admissionType as CompAdmissionType;
    if (!name) {
      setCompTicketErrorMessage("Name is required.");
      return;
    }
    if (!Number.isFinite(quantity) || quantity < 0) {
      setCompTicketErrorMessage("Enter a valid quantity.");
      return;
    }
    setActiveCompTicketActionId(`comp-entry-${editingCompEntryRowId}`);
    setCompTicketErrorMessage(null);
    try {
      const supabase = createClient();
      if (editingCompEntryRowId.startsWith("comp-")) {
        const id = editingCompEntryRowId.replace("comp-", "");
        const current = compTickets.find((item) => item.id === id);
        const checkedInCount = clampCheckedInCount(current?.checked_in_count ?? 0, Math.max(1, quantity));
        const { data, error } = await supabase
          .from("show_comp_tickets")
          .update({
            guest_name: name,
            ticket_count: Math.max(1, quantity),
            ticket_type: "complimentary",
            notes: normalizeOptionalField(buildCompCategoryNotes(editingCompEntryFormState.notes, category, admissionType)),
            checked_in: checkedInCount >= Math.max(1, quantity),
            checked_in_count: checkedInCount,
          })
          .eq("id", id)
          .eq("show_id", show.id)
          .select("*")
          .single();
        if (error) throw error;
        setCompTickets((currentItems) => sortShowCompTickets(currentItems.map((item) => item.id === id ? normalizeShowCompTicket(data as ShowCompTicket) : item)));
      } else if (editingCompEntryRowId.startsWith("reserved-comp-")) {
        const currentRow = buildCompListReportRows().find((row) => row.id === editingCompEntryRowId);
        const originalName = currentRow?.name.trim().toLowerCase() ?? "";
        const assignmentIds = sponsorTicketReservedAssignments
          .filter((assignment) => (assignment.customer_name?.trim().toLowerCase() ?? "") === originalName)
          .map((assignment) => assignment.id);
        if (assignmentIds.length > 0) {
          const nextSeatCategory = category === "guest" ? "guest" : "comp";
          const linkIds = Array.from(new Set(sponsorTicketReservedAssignments
            .filter((assignment) => assignmentIds.includes(assignment.id) && assignment.seating_link_id)
            .map((assignment) => assignment.seating_link_id!)
          ));
          const nextSourceNote = buildCompCategoryNotes(currentRow?.notes, category, admissionType);
          const { error } = await supabase
            .from("show_reserved_seat_assignments")
            .update({ customer_name: name, seat_category: nextSeatCategory })
            .in("id", assignmentIds)
            .eq("show_id", show.id);
          if (error) throw error;
          if (linkIds.length > 0) {
            const { error: linkError } = await supabase
              .from("show_reserved_seating_links")
              .update({ customer_name: name, source_note: nextSourceNote, seat_category: nextSeatCategory, is_complimentary: true })
              .in("id", linkIds)
              .eq("show_id", show.id);
            if (linkError) throw linkError;
            setSponsorTicketReservedLinks((currentLinks) => currentLinks.map((link) => linkIds.includes(link.id) ? { ...link, customer_name: name, source_note: nextSourceNote, seat_category: nextSeatCategory, is_complimentary: true } : link));
          }
          setSponsorTicketReservedAssignments((currentAssignments) => currentAssignments.map((assignment) => assignmentIds.includes(assignment.id) ? { ...assignment, customer_name: name, seat_category: nextSeatCategory } : assignment));
        }
      } else if (editingCompEntryRowId.startsWith("sponsor-")) {
        const id = editingCompEntryRowId.replace("sponsor-", "");
        const { error } = await supabase
          .from("show_sponsors")
          .update({ custom_note: normalizeOptionalField(name), comp_ticket_allowance: Math.max(0, quantity), recognition_notes: normalizeOptionalField(buildCompCategoryNotes(editingCompEntryFormState.notes, category, admissionType)) })
          .eq("id", id)
          .eq("show_id", show.id);
        if (error) throw error;
        setShowSponsors((currentSponsors) => currentSponsors.map((sponsor) => sponsor.id === id ? { ...sponsor, custom_note: normalizeOptionalField(name), comp_ticket_allowance: Math.max(0, quantity), recognition_notes: normalizeOptionalField(buildCompCategoryNotes(editingCompEntryFormState.notes, category, admissionType)) } : sponsor));
      }
      closeEditingCompEntry();
      setCompTicketStatusMessage("Comp entry updated.");
    } catch (error) {
      setCompTicketErrorMessage(getErrorMessage(error));
    } finally {
      setActiveCompTicketActionId(null);
    }
  }

  async function handleDeleteCompEntry(row: CompListReportRow) {
    if (row.id.startsWith("comp-")) {
      const item = compTickets.find((ticket) => ticket.id === row.id.replace("comp-", ""));
      if (item) await handleDeleteCompTicket(item);
      return;
    }
    if (row.id.startsWith("sponsor-") && show) {
      const id = row.id.replace("sponsor-", "");
      setActiveCompTicketActionId(`delete-${row.id}`);
      try {
        const { error } = await createClient().from("show_sponsors").update({ comp_ticket_allowance: 0 }).eq("id", id).eq("show_id", show.id);
        if (error) throw error;
        setShowSponsors((currentSponsors) => currentSponsors.map((sponsor) => sponsor.id === id ? { ...sponsor, comp_ticket_allowance: 0 } : sponsor));
        setCompTicketStatusMessage("Comp entry deleted.");
      } catch (error) {
        setCompTicketErrorMessage(getErrorMessage(error));
      } finally {
        setActiveCompTicketActionId(null);
      }
    }
  }
  const {
    buildCompListReportRows,
    buildSponsorCompListPrintHtml,
    buildSponsorTicketPrintHtml,
    buildCompTicketPrintHtml,
    buildGeneralAdmissionTicketPrintHtml,
    getCompTicketPrintRows,
    getCompAdmissionTypeLabel,
    classifyCompTicket,
  } = createTicketPrintBuilders({
    show,
    sponsorsWithCompTickets,
    compTickets,
    sponsorTicketReservedLinks,
    sponsorTicketReservedAssignments,
    sponsorTicketSponsorId,
    selectedSponsorTicketSeatIds,
    activeSponsorTicketTemplateUrl,
    activeGeneralTicketTemplateUrl,
    activeGeneralAdmissionTicketTemplateUrl,
    generalAdmissionTicketFormState,
    getSponsorTicketSponsorName,
    normalizeGuestListTicketType,
    stripCompMetadataFromNotes,
    sortReservedSeatIds,
    formatReservedSeatLabel,
    formatShowDate,
    escapeHtml,
  });
  function openSponsorCompListPrintWindow(printMode: "print" | "pdf") {
    const printWindow = window.open("", "_blank");
    if (!printWindow) {
      setCompTicketErrorMessage("The print window was blocked. Please allow pop-ups and try again.");
      return;
    }
    printWindow.document.open();
    printWindow.document.write(buildSponsorCompListPrintHtml({ printMode }));
    printWindow.document.close();
    setCompTicketStatusMessage(printMode === "pdf" ? "Use Save as PDF in the print dialog to export the comp list." : "Sponsor & comp ticket list opened.");
  }
  function openGeneralAdmissionTicketPrintWindow(printMode: "print" | "pdf" = "print") {
    if (!activeGeneralAdmissionTicketTemplateUrl) {
      setSponsorTicketErrorMessage("Choose or upload a General Admission ticket template before printing.");
      return;
    }
    const html = buildGeneralAdmissionTicketPrintHtml(printMode);
    if (!html) {
      setSponsorTicketErrorMessage("General Admission tickets could not be generated.");
      return;
    }
    const printWindow = window.open("", "_blank");
    if (!printWindow) {
      setSponsorTicketErrorMessage("The print window was blocked. Please allow pop-ups and try again.");
      return;
    }
    printWindow.document.open();
    printWindow.document.write(html);
    printWindow.document.close();
    setSponsorTicketStatusMessage("General Admission ticket print view opened.");
  }
  function openCompTicketPrintWindow(scope: CompTicketPrintScope, printMode: "print" | "pdf" = "print") {
    const rows = getCompTicketPrintRows(scope);
    const needsSponsorTemplate = rows.some((row) => row.category === "sponsor");
    const needsGeneralTemplate = rows.some((row) => row.category !== "sponsor");
    if ((needsSponsorTemplate && !activeSponsorTicketTemplateUrl) || (needsGeneralTemplate && !activeGeneralTicketTemplateUrl)) {
      setSponsorTicketErrorMessage("Choose the needed Sponsor and General Comp ticket templates before printing comp tickets.");
      return;
    }
    const html = buildCompTicketPrintHtml({ printMode, scope });
    if (!html) {
      setSponsorTicketErrorMessage("No comp tickets are available for that print option.");
      return;
    }
    const printWindow = window.open("", "_blank");
    if (!printWindow) {
      setSponsorTicketErrorMessage("The print window was blocked. Please allow pop-ups and try again.");
      return;
    }
    printWindow.document.open();
    printWindow.document.write(html);
    printWindow.document.close();
    setSponsorTicketStatusMessage("Comp ticket print view opened.");
  }
  function openSponsorTicketPrintWindow(printMode: "print" | "pdf") {
    if (!activeSponsorTicketTemplateUrl) {
      setSponsorTicketErrorMessage("Upload or choose a ticket template image before printing sponsor tickets.");
      return;
    }
    if (!sponsorTicketSponsorId) {
      setSponsorTicketErrorMessage("Choose a sponsor before printing sponsor tickets.");
      return;
    }
    if (selectedSponsorTicketSeatIds.length === 0) {
      setSponsorTicketErrorMessage("Select at least one reserved comp seat before printing sponsor tickets.");
      return;
    }

    const html = buildSponsorTicketPrintHtml({ printMode });
    if (!html) {
      setSponsorTicketErrorMessage("Ticket information is incomplete. Check the template, sponsor, and reserved seats before printing.");
      return;
    }
    const printWindow = window.open("", "_blank");
    if (!printWindow) {
      setSponsorTicketErrorMessage("The print window was blocked. Please allow pop-ups and try again.");
      return;
    }
    printWindow.document.open();
    printWindow.document.write(html);
    printWindow.document.close();
    setSponsorTicketStatusMessage(printMode === "pdf" ? "Use Save as PDF in the print dialog to export the tickets." : "Ticket print view opened.");
  }
  async function handleCheckInCustomSponsorCompAmount(sponsor: ShowSponsor) {
    const customAmount = parseNonNegativeIntegerInput(sponsorCompCustomAmounts[sponsor.id] ?? "");

    if (customAmount === null || customAmount <= 0) {
      setCompTicketErrorMessage("Enter a valid sponsor comp check-in amount.");
      return;
    }

    await handleAdjustSponsorCompCheckIn(sponsor, customAmount, {
      source: "custom",
    });
  }

  async function handlePreviewPaidOnlineGuestList(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!show) {
      setCompTicketErrorMessage("The show is not loaded yet.");
      return;
    }

    const parsedEntries =
      compTicketImportSource === "square_csv"
        ? parseSquareCsvImportText(compTicketImportText)
        : parseGuestListImportText(compTicketImportText);

    if (parsedEntries.length === 0) {
      setCompTicketErrorMessage(
        compTicketImportSource === "square_csv"
          ? "Could not parse Square CSV."
          : "Paste website ticket order text to import paid online entries.",
      );
      return;
    }

    setCompTicketErrorMessage(null);
    setCompTicketStatusMessage(null);
    const existingPaidOnlineTickets = compTickets.filter(
      (item) => normalizeGuestListTicketType(item.ticket_type) === "paid_online",
    );
    setCompTicketImportPreview(
      parsedEntries.map((entry) =>
        buildPaidOnlineImportPreviewEntry(show.id, entry, existingPaidOnlineTickets),
      ),
    );
  }

  async function handleConfirmPaidOnlineGuestListImport() {
    if (!show) {
      setCompTicketErrorMessage("The show is not loaded yet.");
      return;
    }

    const newEntries = compTicketImportPreview.filter((entry) => entry.status === "new");

    if (newEntries.length === 0) {
      setCompTicketErrorMessage("There are no new paid online orders to import.");
      return;
    }

    setCompTicketErrorMessage(null);
    setCompTicketStatusMessage(null);
    setActiveCompTicketActionId("import");

    try {
      const supabase = createClient();
      const payload = newEntries.map((entry) => ({
        show_id: show.id,
        guest_name: entry.guestName,
        email: normalizeOptionalField(entry.email),
        ticket_count: entry.ticketCount,
        ticket_type: "paid_online",
        order_id: normalizeOptionalField(entry.orderId),
        import_key: entry.importKey,
        notes: normalizeOptionalField(entry.notes),
        checked_in: false,
        checked_in_count: entry.checkedInCount,
      }));

      const { data, error } = await supabase
        .from("show_comp_tickets")
        .insert(payload)
        .select("*");

      if (error) {
        throw error;
      }

      const importedEntries = ((data ?? []) as Array<
        Omit<ShowCompTicket, "ticket_count" | "checked_in_count"> & {
          ticket_count: number | string | null;
          checked_in_count?: number | string | null;
        }
      >).map((item) => normalizeShowCompTicket(item));

      const reservedSeatingSync = await syncReservedSeatingLinksForImportedOrders(
        supabase,
        show.id,
        importedEntries,
      );

      setCompTickets((currentItems) => sortShowCompTickets([...currentItems, ...importedEntries]));
      setCompTicketImportPreview([]);
      setCompTicketImportText("");

      const importSummaryParts = [
        `Imported ${importedEntries.length} new paid online order entr${importedEntries.length === 1 ? "y" : "ies"}.`,
        reservedSeatingSync.createdCount > 0
          ? `Added ${reservedSeatingSync.createdCount} reserved seating link${reservedSeatingSync.createdCount === 1 ? "" : "s"}.`
          : null,
        reservedSeatingSync.updatedCount > 0
          ? `Updated ${reservedSeatingSync.updatedCount} reserved seating record${reservedSeatingSync.updatedCount === 1 ? "" : "s"}.`
          : null,
        reservedSeatingSync.warnings.length > 0
          ? `Warnings: ${reservedSeatingSync.warnings.join(" ")}`
          : null,
      ].filter((value): value is string => Boolean(value));

      setCompTicketStatusMessage(importSummaryParts.join(" "));
    } catch (error) {
      setCompTicketErrorMessage(getErrorMessage(error));
    } finally {
      setActiveCompTicketActionId(null);
    }
  }

  async function handleQuickAddGuestPayout(guestProfile: GuestProfile) {
    if (!show) {
      setPayoutErrorMessage("The show is not loaded yet.");
      return;
    }

    const payeeName = guestProfile.name?.trim();

    if (!payeeName) {
      setPayoutErrorMessage("Guest name is missing.");
      return;
    }

    setPayoutErrorMessage(null);
    setPayoutStatusMessage(null);
    setActivePayoutActionId(`guest-${guestProfile.id}`);

    try {
      const supabase = createClient();
      const { data, error } = await supabase
        .from("show_payout_items")
        .insert({
          show_id: show.id,
          payee_name: payeeName,
          category: "Guest",
          description: null,
          amount: 0,
          paid: false,
          payment_method: null,
        })
        .select("*")
        .single();

      if (error) {
        throw error;
      }

      setPayoutItems((currentItems) =>
        sortShowPayoutItems([
          ...currentItems,
          normalizeShowPayoutItem(data as ShowPayoutItem),
        ]),
      );
      setPayoutStatusMessage(`Added ${payeeName} to the payout sheet.`);
    } catch (error) {
      setPayoutErrorMessage(getErrorMessage(error));
    } finally {
      setActivePayoutActionId(null);
    }
  }

  function handlePrintPayoutSheet() {
    if (!show) {
      setPayoutErrorMessage("The show is not loaded yet.");
      return;
    }

    setPayoutErrorMessage(null);
    const printHtml = buildPayoutSheetHtml({
      showName: show.name,
      showDate: show.show_date,
      payoutItems,
    });
    openPrintDocumentWindow(printHtml);
  }

  function handlePrintFinanceReport() {
    const printWindow = window.open("", "_blank");

    if (!printWindow) {
      window.alert("The print window was blocked. Please allow pop-ups and try again.");
      return;
    }

    const printHtml = buildFinanceReportHtml({
      showName: show?.name ?? "Show",
      showDate: show?.show_date ?? null,
      venue: show?.venue ?? null,
      financeItems,
    });

    const triggerPrint = () => {
      if (printWindow.closed) {
        return;
      }

      printWindow.focus();
      printWindow.print();
    };

    printWindow.onload = triggerPrint;
    printWindow.onafterprint = () => {
      printWindow.close();
    };

    const { document } = printWindow;
    document.open();
    document.write(printHtml);
    document.close();

    if (document.readyState === "complete") {
      triggerPrint();
    }
  }

  const loadShowData = useCallback(
    async (showSpinner = true) => {
      if (showSpinner) {
        setIsLoading(true);
      }

      setErrorMessage(null);
      setDataSectionErrors({});

      try {
        const supabase = createClient();

        const { data: showRecord, error: showError } = await supabase
          .from("shows")
          .select("*")
          .eq("slug", showSlug)
          .maybeSingle();

        if (showError) {
          throw showError;
        }

        if (!showRecord) {
          setShow(null);
          setSetlist([]);
          setPendingSongs([]);
          setSongLibrary([]);
          setRehearsalEntries([]);
          setRehearsalRecordings([]);
          setRehearsalTitleDrafts({});
          setRehearsalKeyDrafts({});
          setRehearsalSungByDrafts({});
          setRehearsalNoteDrafts({});
          setOpenRehearsalEntryIds({});
          setSponsorLibrary([]);
          setPotentialSponsors([]);
          setShowSponsors([]);
          setShowChecklistItems([]);
          setCompTickets([]);
          setFinanceItems([]);
          setPayoutItems([]);
          setPromoLinks([]);
          setPromoMaterials([]);
          setGuestProfiles([]);
          setMcBlockNotes([]);
          setMcSponsorReads([]);
          setErrorMessage("Show not found");
          return;
        }

        setShow(showRecord);

        const sectionErrors: DataSectionErrors = {};
        const loadSection = async <T,>(
          sectionKey: DataSectionKey,
          sectionName: string,
          query: PromiseLike<{ data: T | null; error: unknown }>,
          fallback: T,
        ) => {
          try {
            const result = await query;

            if (result.error) {
              sectionErrors[sectionKey] = getErrorMessage(result.error);
              logDataSectionError(sectionName, result.error);
              return fallback;
            }

            return result.data ?? fallback;
          } catch (error) {
            sectionErrors[sectionKey] = getErrorMessage(error);
            logDataSectionError(sectionName, error);
            return fallback;
          }
        };

        const [
          setlistRows,
          pendingRows,
          libraryRows,
          rehearsalEntryRows,
          rehearsalRecordingRows,
          sponsorLibraryRows,
          potentialSponsorRows,
          showSponsorRows,
          checklistItemRows,
          compTicketRows,
          financeItemRows,
          payoutItemRows,
          promoLinkRows,
          promoMaterialRows,
          guestProfileRows,
          mcBlockNoteRows,
          mcSponsorReadRows,
          mcSpecialSegmentRows,
        ] = await Promise.all([
          loadSection(
            "setlist",
            "setlist entries",
            supabase
              .from("setlist_entries")
              .select(`
                id,
                show_id,
                section,
                position,
                source_type,
                song_id,
                guest_song_id,
                custom_title,
                performance_flow,
              song_intro_notes,
              created_at,
                library_song:song_id (
                  id,
                  title,
                  key,
                  sung_by,
                  tempo,
                  song_type,
                  performance_flow,
                song_intro_notes,
                notes,
                  lyrics,
                  created_by_role,
                  created_by_name,
                  created_at
                ),
          guest_song:guest_song_id (
            id,
            show_id,
            title,
            key,
            sung_by,
            tempo,
            song_type,
            notes,
            lyrics,
            submitted_by_name,
            created_at
          )
              `)
              .eq("show_id", showRecord.id)
              .order("section", { ascending: true })
              .order("position", { ascending: true }),
            [],
          ),
          loadSection(
            "guestSongs",
            "guest songs",
            supabase
              .from("show_guest_songs")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("created_at", { ascending: true }),
            [],
          ),
          loadSection(
            "songLibrary",
            "song library",
            supabase
              .from("songs")
              .select("*")
              .order("title", { ascending: true }),
            [],
          ),
          loadSection(
            "rehearsalEntries",
            "rehearsal entries",
            supabase
              .from("rehearsal_entries")
              .select(`
                *,
                library_song:song_id (
                  id,
                  title,
                  key,
                  sung_by,
                  tempo,
                  song_type,
                  notes,
                  lyrics,
                  created_by_role,
                  created_by_name,
                  created_at
                )
              `)
              .eq("show_id", showRecord.id)
              .order("sort_order", { ascending: true })
              .order("created_at", { ascending: true }),
            [],
          ),
          loadSection(
            "rehearsalRecordings",
            "rehearsal recordings",
            supabase
              .from("rehearsal_recordings")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("created_at", { ascending: false }),
            [],
          ),
          loadSection(
            "sponsorLibrary",
            "sponsor library",
            supabase
              .from("sponsor_library")
              .select("*")
              .order("name", { ascending: true }),
            [],
          ),
          loadSection(
            "potentialSponsors",
            "potential sponsors",
            requestPotentialSponsorsApi<PotentialSponsor[]>()
              .then((data) => ({ data, error: null }))
              .catch((error) => ({ data: null, error })),
            [],
          ),
          loadSection(
            "showSponsors",
            "show sponsors",
            supabase
              .from("show_sponsors")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("placement_order", { ascending: true })
              .order("created_at", { ascending: true }),
            [],
          ),
          loadSection(
            "checklistItems",
            "show checklist items",
            supabase
              .from("show_checklist_items")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("created_at", { ascending: true }),
            [],
          ),
          loadSection(
            "compTickets",
            "show comp tickets",
            supabase
              .from("show_comp_tickets")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("created_at", { ascending: true }),
            [],
          ),
          loadSection(
            "financeItems",
            "finance items",
            supabase
              .from("show_finance_items")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("created_at", { ascending: false }),
            [],
          ),
          loadSection(
            "payoutItems",
            "show payout items",
            supabase
              .from("show_payout_items")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("created_at", { ascending: true }),
            [],
          ),
          loadSection(
            "promoLinks",
            "promo links",
            supabase
              .from("promo_links")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("created_at", { ascending: false }),
            [],
          ),
          loadSection(
            "promoMaterials",
            "promo materials",
            supabase
              .from("promo_materials")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("created_at", { ascending: false }),
            [],
          ),
          loadSection(
            "guestProfiles",
            "guest profiles",
            supabase
              .from("guest_profiles")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("created_at", { ascending: true }),
            [],
          ),
          loadSection(
            "mcBlockNotes",
            "MC block notes",
            supabase
              .from("mc_block_notes")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("created_at", { ascending: true }),
            [],
          ),
          loadSection(
            "mcBuilder",
            "MC sponsor reads",
            supabase
              .from("mc_sponsor_reads")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("placement_order", { ascending: true })
              .order("created_at", { ascending: true }),
            [],
          ),
          loadSection(
            "mcSpecialSegments",
            "MC special segments",
            supabase
              .from("mc_special_segments")
              .select("*")
              .eq("show_id", showRecord.id)
              .order("placement_order", { ascending: true })
              .order("created_at", { ascending: true }),
            [],
          ),
        ]);

        const guestSongStoragePathById = new Map<string, string>();
        const guestSongStoragePrefix = `song-audio/shows/${sanitizeFileName(showRecord.slug || "show")}/songs`;

        try {
          const { data: guestSongMp3Objects, error: guestSongMp3ListError } = await supabase.storage
            .from(SONG_AUDIO_BUCKET)
            .list(guestSongStoragePrefix, { limit: 1000 });

          if (guestSongMp3ListError) {
            logDataSectionError("guest song MP3 attachments", guestSongMp3ListError);
          } else {
            for (const guestSongMp3Object of guestSongMp3Objects ?? []) {
              const objectName = guestSongMp3Object.name ?? "";
              const match = objectName.match(/^([0-9a-f-]+)\.mp3$/i);

              if (match) {
                guestSongStoragePathById.set(
                  match[1],
                  `${guestSongStoragePrefix}/${objectName}`,
                );
              }
            }
          }
        } catch (error) {
          logDataSectionError("guest song MP3 attachments", error);
        }

        setSetlist(
          sortSetlistSongs(
            (setlistRows ?? []).map((song: SetlistEntryQueryRow) =>
              normalizeSetlistSong(song),
            ),
          ),
        );
        setPendingSongs(
          (pendingRows ?? []).map((submission: PendingSubmission) =>
            normalizePendingSubmission(
              submission,
              guestSongStoragePathById.get(submission.id) ?? null,
            ),
          ),
        );
        setSongLibrary(
          (libraryRows ?? []).map((song: SongLibrarySong) => normalizeSongLibrarySong(song)),
        );
        const normalizedRehearsalEntries = sortRehearsalEntries(
          ((rehearsalEntryRows ?? []) as RehearsalEntryRow[]).map((entry) =>
            normalizeRehearsalEntry(entry),
          ),
        );
        setRehearsalEntries(normalizedRehearsalEntries);
        setRehearsalTitleDrafts(
          normalizedRehearsalEntries.reduce<Record<string, string>>((lookup, entry) => {
            lookup[entry.id] = entry.title;
            return lookup;
          }, {}),
        );
        setRehearsalKeyDrafts(
          normalizedRehearsalEntries.reduce<Record<string, string>>((lookup, entry) => {
            lookup[entry.id] = entry.song_key ?? "";
            return lookup;
          }, {}),
        );
        setRehearsalSungByDrafts(
          normalizedRehearsalEntries.reduce<Record<string, string>>((lookup, entry) => {
            lookup[entry.id] = entry.sung_by ?? "";
            return lookup;
          }, {}),
        );
        setRehearsalNoteDrafts(
          normalizedRehearsalEntries.reduce<Record<string, string>>((lookup, entry) => {
            lookup[entry.id] = entry.notes ?? "";
            return lookup;
          }, {}),
        );
        setOpenRehearsalEntryIds(
          normalizedRehearsalEntries.reduce<Record<string, boolean>>((lookup, entry) => {
            lookup[entry.id] = false;
            return lookup;
          }, {}),
        );
        setRehearsalRecordings(
          sortRehearsalRecordings(
            ((rehearsalRecordingRows ?? []) as RehearsalRecording[]).map((recording) =>
              normalizeRehearsalRecording(recording),
            ),
          ),
        );
        const normalizedSponsorLibrary = (sponsorLibraryRows ?? []).map(
          (sponsor: SponsorLibraryEntry) => normalizeSponsorLibraryEntry(sponsor),
        );
        setSponsorLibrary(normalizedSponsorLibrary);
        setPotentialSponsors(
          sortPotentialSponsors(
            (potentialSponsorRows ?? []).map((potentialSponsor: PotentialSponsor) =>
              normalizePotentialSponsorEntry(potentialSponsor),
            ),
          ),
        );
        setShowSponsors(
          mergeShowSponsorsWithLibrary((showSponsorRows ?? []) as ShowSponsor[], normalizedSponsorLibrary),
        );
        setShowChecklistItems(
          sortShowChecklistItems((checklistItemRows ?? []) as ShowChecklistItem[]),
        );
        setCompTickets(
          sortShowCompTickets(
            ((compTicketRows ?? []) as Array<
              Omit<ShowCompTicket, "ticket_count"> & { ticket_count: number | string | null }
            >).map((item) => normalizeShowCompTicket(item)),
          ),
        );
        setFinanceItems(
          sortFinanceItems(
            ((financeItemRows ?? []) as Array<
              Omit<ShowFinanceItem, "amount"> & { amount: number | string | null }
            >).map((item) => normalizeShowFinanceItem(item)),
          ),
        );
        setPayoutItems(
          sortShowPayoutItems(
            ((payoutItemRows ?? []) as Array<
              Omit<ShowPayoutItem, "amount"> & { amount: number | string | null }
            >).map((item) => normalizeShowPayoutItem(item)),
          ),
        );
        setPromoLinks((promoLinkRows ?? []) as PromoLink[]);
        setPromoMaterials((promoMaterialRows ?? []) as PromoMaterial[]);
        setGuestProfiles(guestProfileRows ?? []);
        setMcBlockNotes((mcBlockNoteRows ?? []) as McBlockNote[]);
        setMcSponsorReads(sortMcSponsorReads((mcSponsorReadRows ?? []) as McSponsorRead[]));
        setMcSpecialSegments((mcSpecialSegmentRows ?? []) as McSpecialSegment[]);
        setDataSectionErrors(sectionErrors);
      } catch (error) {
        setErrorMessage(getErrorMessage(error));
      } finally {
        if (showSpinner) {
          setIsLoading(false);
        }
      }
    },
    [showSlug],
  );

