  function toggleCollapsedMcSong(songId: string) {
    setCollapsedMcSongIds((currentIds) =>
      currentIds.includes(songId)
        ? currentIds.filter((currentId) => currentId !== songId)
        : [...currentIds, songId],
    );
  }

  function toggleCollapsedMcSegment(segmentId: string) {
    setCollapsedMcSegmentIds((currentIds) =>
      currentIds.includes(segmentId)
        ? currentIds.filter((currentId) => currentId !== segmentId)
        : [...currentIds, segmentId],
    );
  }

  function handleCollapseAllMcBuilderItems() {
    setCollapsedMcSongIds(mcBuilderValidSongIds);
    setCollapsedMcSponsorIds(mcBuilderValidSponsorIds);
    setCollapsedMcSegmentIds(mcBuilderValidSegmentIds);
    setExpandedMcBlockNoteIds([]);
  }

  function handleExpandAllMcBuilderItems() {
    setCollapsedMcSongIds([]);
    setCollapsedMcSponsorIds([]);
    setCollapsedMcSegmentIds([]);
    setExpandedMcBlockNoteIds(mcBuilderValidBlockNoteIds);
  }

  function getMcInsertPlacementOrder(targetIndex: number | null) {
    if (targetIndex === null || targetIndex < 0) {
      const existingOrders = [
        ...mcSponsorReads.map((read) => read.placement_order),
        ...mcSpecialSegments.map((segment) => segment.placement_order),
      ];

      return existingOrders.length > 0 ? Math.max(...existingOrders) + 1 : 1;
    }

    return (
      adminMcSponsorPlacementItems
        .slice(0, targetIndex)
        .filter((item) => item.kind === "sponsor" || item.kind === "segment").length + 1
    );
  }

  function buildMcSpecialSegmentPayload(formState: McSpecialSegmentFormState) {
    return {
      title: formState.title.trim(),
      notes: normalizeOptionalField(formState.notes),
      placement_type: normalizeOptionalField(formState.placementType),
      anchor_song_id:
        formState.placementType === "before_performer" || formState.placementType === "after_performer"
          ? normalizeOptionalField(formState.anchorSongId)
          : null,
      anchor_sponsor_read_id:
        formState.placementType === "after_sponsor_read"
          ? normalizeOptionalField(formState.anchorSponsorReadId)
          : null,
    };
  }

  function startEditingMcSpecialSegment(segment: McSpecialSegment) {
    setEditingMcSpecialSegmentId(segment.id);
    setEditingMcSpecialSegmentFormState({
      title: segment.title,
      notes: segment.notes ?? "",
      placementType: segment.placement_type ?? "after_performer",
      anchorSongId: segment.anchor_song_id ?? "",
      anchorSponsorReadId: segment.anchor_sponsor_read_id ?? "",
    });
  }

  function cancelEditingMcSpecialSegment() {
    setEditingMcSpecialSegmentId(null);
    setEditingMcSpecialSegmentFormState(initialMcSpecialSegmentFormState);
  }

  async function handleCreateMcSpecialSegment(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!show) {
      setMcErrorMessage("The show is not loaded yet.");
      return;
    }

    const payload = buildMcSpecialSegmentPayload(mcSpecialSegmentFormState);

    if (!payload.title) {
      setMcErrorMessage("Add a title for this special segment.");
      return;
    }

    if (
      mcSpecialSegmentFormState.placementType === "after_sponsor_read" &&
      !payload.anchor_sponsor_read_id
    ) {
      setMcErrorMessage("Choose which sponsor read this segment should follow.");
      return;
    }

    setMcErrorMessage(null);
    setMcStatusMessage(null);
    setActiveSponsorActionId("mc-special-segment-create");

    try {
      const supabase = createClient();
      const insertOrder = getMcInsertPlacementOrder(pendingMcSpecialSegmentInsertIndex);
      const shiftedSponsorReads = mcSponsorReads
        .filter((read) => read.placement_order >= insertOrder)
        .map((read) => ({ ...read, placement_order: read.placement_order + 1 }));
      const shiftedSegments = mcSpecialSegments
        .filter((segment) => segment.placement_order >= insertOrder)
        .map((segment) => ({ ...segment, placement_order: segment.placement_order + 1 }));

      for (const sponsorRead of shiftedSponsorReads) {
        const { error } = await supabase
          .from("mc_sponsor_reads")
          .update({ placement_order: sponsorRead.placement_order })
          .eq("id", sponsorRead.id)
          .eq("show_id", show.id);

        if (error) {
          throw error;
        }
      }

      for (const segment of shiftedSegments) {
        const { error } = await supabase
          .from("mc_special_segments")
          .update({ placement_order: segment.placement_order })
          .eq("id", segment.id)
          .eq("show_id", show.id);

        if (error) {
          throw error;
        }
      }

      const { data, error } = await supabase
        .from("mc_special_segments")
        .insert({
          show_id: show.id,
          placement_order: insertOrder,
          ...payload,
        })
        .select("*")
        .single();

      if (error) {
        throw error;
      }

      setMcSponsorReads((currentReads) =>
        sortMcSponsorReads(
          currentReads.map((read) => {
            const shiftedRead = shiftedSponsorReads.find((candidate) => candidate.id === read.id);
            return shiftedRead ?? read;
          }),
        ),
      );
      setMcSpecialSegments((currentSegments) =>
        [
          ...currentSegments.map((segment) => {
            const shiftedSegment = shiftedSegments.find((candidate) => candidate.id === segment.id);
            return shiftedSegment ?? segment;
          }),
          data as McSpecialSegment,
        ].sort((segmentA, segmentB) => {
          if (segmentA.placement_order !== segmentB.placement_order) {
            return segmentA.placement_order - segmentB.placement_order;
          }

          return segmentA.created_at.localeCompare(segmentB.created_at);
        }),
      );
      setMcSpecialSegmentFormState(initialMcSpecialSegmentFormState);
      setIsMcSpecialSegmentFormOpen(false);
      setPendingMcSpecialSegmentInsertIndex(null);
      await loadShowData(false);
      setMcStatusMessage("Special segment added to MC flow.");
    } catch (error) {
      setMcErrorMessage(getErrorMessage(error));
    } finally {
      setActiveSponsorActionId(null);
    }
  }

  async function handleCreateMcSponsorRead(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!show) {
      setMcErrorMessage("The show is not loaded yet.");
      return;
    }

    const selectedShowSponsor = showSponsors.find(
      (sponsor) => sponsor.id === mcSponsorReadFormState.showSponsorId,
    );

    if (!selectedShowSponsor) {
      setMcErrorMessage("Choose a show sponsor first.");
      return;
    }

    setMcErrorMessage(null);
    setMcStatusMessage(null);
    setActiveSponsorActionId(`mc-sponsor-read-${selectedShowSponsor.id}`);

    try {
      const supabase = createClient();
      const nextPlacementOrder = getMcInsertPlacementOrder(pendingMcSponsorInsertIndex);
      const anchorSongId =
        mcSponsorReadFormState.placementType === "before_performer" ||
        mcSponsorReadFormState.placementType === "after_performer"
          ? normalizeOptionalField(mcSponsorReadFormState.anchorSongId)
          : null;
      const linkedPerformer = anchorSongId
        ? getDisplaySingerName(setlist.find((song) => song.id === anchorSongId)?.artist ?? null)
        : null;

      if (
        selectedShowSponsor.sponsor_id &&
        mcSponsorReadFormState.scriptText.trim() &&
        mcSponsorReadFormState.scriptText.trim() !== getSponsorReadText(selectedShowSponsor)
      ) {
        const sponsorLibraryId = selectedShowSponsor.sponsor_id;
        const { error: sponsorLibraryError } = await supabase
          .from("sponsor_library")
          .update({ full_message: mcSponsorReadFormState.scriptText.trim() })
          .eq("id", sponsorLibraryId);

        if (sponsorLibraryError) {
          throw sponsorLibraryError;
        }

        setSponsorLibrary((currentLibrary) =>
          currentLibrary.map((sponsor) =>
            sponsor.id === sponsorLibraryId
              ? {
                  ...sponsor,
                  full_message: mcSponsorReadFormState.scriptText.trim(),
                }
              : sponsor,
          ),
        );
        setShowSponsors((currentSponsors) =>
          updateSponsorReadTextInAssignments(
            currentSponsors,
            sponsorLibraryId,
            mcSponsorReadFormState.scriptText.trim(),
          ),
        );
      }

      const shiftedSponsorReads = mcSponsorReads
        .filter((read) => read.placement_order >= nextPlacementOrder)
        .map((read) => ({ ...read, placement_order: read.placement_order + 1 }));
      const shiftedSegments = mcSpecialSegments
        .filter((segment) => segment.placement_order >= nextPlacementOrder)
        .map((segment) => ({ ...segment, placement_order: segment.placement_order + 1 }));

      for (const sponsorRead of shiftedSponsorReads) {
        const { error } = await supabase
          .from("mc_sponsor_reads")
          .update({ placement_order: sponsorRead.placement_order })
          .eq("id", sponsorRead.id)
          .eq("show_id", show.id);

        if (error) {
          throw error;
        }
      }

      for (const segment of shiftedSegments) {
        const { error } = await supabase
          .from("mc_special_segments")
          .update({ placement_order: segment.placement_order })
          .eq("id", segment.id)
          .eq("show_id", show.id);

        if (error) {
          throw error;
        }
      }

      const { data, error } = await supabase
        .from("mc_sponsor_reads")
        .insert({
          show_id: show.id,
          show_sponsor_id: selectedShowSponsor.id,
          placement_order: nextPlacementOrder,
          placement_type: normalizeOptionalField(mcSponsorReadFormState.placementType),
          anchor_song_id: anchorSongId,
          linked_performer: linkedPerformer,
          custom_note: normalizeOptionalField(mcSponsorReadFormState.customNote),
        })
        .select("*")
        .single();

      if (error) {
        throw error;
      }

      setMcSponsorReads((currentReads) =>
        sortMcSponsorReads([
          ...currentReads.map((read) => {
            const shiftedRead = shiftedSponsorReads.find((candidate) => candidate.id === read.id);
            return shiftedRead ?? read;
          }),
          data as McSponsorRead,
        ]),
      );
      setMcSpecialSegments((currentSegments) =>
        currentSegments.map((segment) => {
          const shiftedSegment = shiftedSegments.find((candidate) => candidate.id === segment.id);
          return shiftedSegment ?? segment;
        }),
      );
      setMcSponsorReadFormState(initialMcSponsorReadFormState);
      setIsMcSponsorReadFormOpen(false);
      setPendingMcSponsorInsertIndex(null);
      setMcStatusMessage("Sponsor read added to MC flow.");
    } catch (error) {
      setMcErrorMessage(getErrorMessage(error));
    } finally {
      setActiveSponsorActionId(null);
    }
  }

  async function handleSaveMcSpecialSegment(segmentId: string) {
    if (!show) {
      setMcErrorMessage("The show is not loaded yet.");
      return;
    }

    const payload = buildMcSpecialSegmentPayload(editingMcSpecialSegmentFormState);

    if (!payload.title) {
      setMcErrorMessage("Add a title for this special segment.");
      return;
    }

    if (
      editingMcSpecialSegmentFormState.placementType === "after_sponsor_read" &&
      !payload.anchor_sponsor_read_id
    ) {
      setMcErrorMessage("Choose which sponsor read this segment should follow.");
      return;
    }

    setMcErrorMessage(null);
    setMcStatusMessage(null);
    setActiveSponsorActionId(`mc-special-segment-${segmentId}`);

    try {
      const supabase = createClient();
      const { data, error } = await supabase
        .from("mc_special_segments")
        .update(payload)
        .eq("id", segmentId)
        .eq("show_id", show.id)
        .select("*")
        .single();

      if (error) {
        throw error;
      }

      setMcSpecialSegments((currentSegments) =>
        currentSegments.map((segment) =>
          segment.id === segmentId ? (data as McSpecialSegment) : segment,
        ),
      );
      cancelEditingMcSpecialSegment();
      setMcStatusMessage("Special segment updated.");
    } catch (error) {
      setMcErrorMessage(getErrorMessage(error));
    } finally {
      setActiveSponsorActionId(null);
    }
  }

  async function handleDeleteMcSpecialSegment(segmentId: string) {
    if (!show) {
      setMcErrorMessage("The show is not loaded yet.");
      return;
    }

    setMcErrorMessage(null);
    setMcStatusMessage(null);
    setActiveSponsorActionId(`mc-special-segment-delete-${segmentId}`);

    try {
      const supabase = createClient();
      const { error } = await supabase
        .from("mc_special_segments")
        .delete()
        .eq("id", segmentId)
        .eq("show_id", show.id);

      if (error) {
        throw error;
      }

      setMcSpecialSegments((currentSegments) =>
        currentSegments
          .filter((segment) => segment.id !== segmentId)
          .map((segment, index) => ({
            ...segment,
            placement_order: index + 1,
          })),
      );
      if (editingMcSpecialSegmentId === segmentId) {
        cancelEditingMcSpecialSegment();
      }
      setMcStatusMessage("Special segment removed.");
    } catch (error) {
      setMcErrorMessage(getErrorMessage(error));
    } finally {
      setActiveSponsorActionId(null);
    }
  }

  async function handleRemoveMcSpecialSegmentFromFlow(segmentId: string) {
    if (!show) {
      setMcErrorMessage("The show is not loaded yet.");
      return;
    }

    setMcErrorMessage(null);
    setMcStatusMessage(null);
    setActiveSponsorActionId(`mc-special-segment-remove-${segmentId}`);

    try {
      const supabase = createClient();
      const { data, error } = await supabase
        .from("mc_special_segments")
        .update({
          placement_type: null,
          anchor_song_id: null,
          anchor_sponsor_read_id: null,
        })
        .eq("id", segmentId)
        .eq("show_id", show.id)
        .select("*")
        .single();

      if (error) {
        throw error;
      }

      setMcSpecialSegments((currentSegments) =>
        currentSegments.map((segment) =>
          segment.id === segmentId ? (data as McSpecialSegment) : segment,
        ),
      );
      if (editingMcSpecialSegmentId === segmentId) {
        cancelEditingMcSpecialSegment();
      }
      setMcStatusMessage("Special segment removed from MC flow.");
    } catch (error) {
      setMcErrorMessage(getErrorMessage(error));
    } finally {
      setActiveSponsorActionId(null);
    }
  }

