  async function handleSaveMcBlockNote(anchorSongId: string) {
    if (!show) {
      setMcErrorMessage("The show is not loaded yet.");
      return;
    }

    const draft = mcBlockNoteDrafts[anchorSongId];

    if (!draft) {
      return;
    }

    const introNote = normalizeOptionalField(draft.introNote);
    const sponsorMention = normalizeOptionalField(draft.sponsorMention);
    const transitionNote = normalizeOptionalField(draft.transitionNote);
    const existingNote = mcBlockNotes.find((note) => note.anchor_song_id === anchorSongId);

    setMcErrorMessage(null);
    setMcStatusMessage(null);
    setActiveMcBlockActionId(anchorSongId);

    try {
      const supabase = createClient();

      if (!introNote && !sponsorMention && !transitionNote) {
        if (existingNote) {
          const { error } = await supabase
            .from("mc_block_notes")
            .delete()
            .eq("id", existingNote.id)
            .eq("show_id", show.id);

          if (error) {
            throw error;
          }

          setMcBlockNotes((currentNotes) =>
            currentNotes.filter((note) => note.id !== existingNote.id),
          );
          setMcStatusMessage("MC block notes cleared.");
        } else {
          setMcStatusMessage("No MC block notes to save.");
        }

        return;
      }

      const { data, error } = await supabase
        .from("mc_block_notes")
        .upsert(
          {
            show_id: show.id,
            anchor_song_id: anchorSongId,
            intro_note: introNote,
            sponsor_mention: sponsorMention,
            transition_note: transitionNote,
          },
          { onConflict: "show_id,anchor_song_id" },
        )
        .select("*")
        .single();

      if (error) {
        throw error;
      }

      setMcBlockNotes((currentNotes) => {
        const existingIndex = currentNotes.findIndex((note) => note.id === data.id);

        if (existingIndex >= 0) {
          return currentNotes.map((note) => (note.id === data.id ? data : note));
        }

        return [...currentNotes, data];
      });
      setMcStatusMessage("MC block notes saved.");
    } catch (error) {
      setMcErrorMessage(getErrorMessage(error));
    } finally {
      setActiveMcBlockActionId(null);
    }
  }

  async function handleMoveMcSponsor(sponsorId: string, direction: "up" | "down") {
    if (!show) {
      setMcErrorMessage("The show is not loaded yet.");
      return;
    }

    const currentIndex = adminMcFlowItems.findIndex(
      (item) => item.kind === "sponsor" && item.sponsor.id === sponsorId,
    );

    if (currentIndex < 0) {
      return;
    }

    const targetIndex = direction === "up" ? currentIndex - 1 : currentIndex + 1;

    if (targetIndex < 0 || targetIndex >= adminMcFlowItems.length) {
      return;
    }

    const currentItem = adminMcFlowItems[currentIndex];
    const neighborItem = adminMcFlowItems[targetIndex];

    if (!currentItem || currentItem.kind !== "sponsor" || !neighborItem) {
      return;
    }

    const reorderedItems = [...adminMcFlowItems];
    [reorderedItems[currentIndex], reorderedItems[targetIndex]] = [
      reorderedItems[targetIndex],
      reorderedItems[currentIndex],
    ];

    const sponsorSequence = reorderedItems.filter(
      (item): item is Extract<McFlowRenderableItem, { kind: "sponsor" }> => item.kind === "sponsor",
    );

    const movedSponsorPlacement = getMcSponsorPlacementFromNeighbor(neighborItem, direction);

    const nextSponsors = showSponsors
      .map((sponsor) => {
        const nextOrder = sponsorSequence.findIndex((item) => item.sponsor.id === sponsor.id);

        if (nextOrder < 0) {
          return sponsor;
        }

        if (sponsor.id === sponsorId) {
          return {
            ...sponsor,
            placement_order: nextOrder + 1,
            placement_type: movedSponsorPlacement.placement_type,
            mc_anchor_song_id: movedSponsorPlacement.mc_anchor_song_id,
            linked_performer: movedSponsorPlacement.linked_performer,
          };
        }

        return {
          ...sponsor,
          placement_order: nextOrder + 1,
        };
      })
      .sort((sponsorA, sponsorB) => sponsorA.placement_order - sponsorB.placement_order);

    setMcErrorMessage(null);
    setMcStatusMessage(null);
    setActiveSponsorActionId(`mc-${sponsorId}`);

    try {
      const supabase = createClient();

      for (const sponsor of nextSponsors) {
        const { error } = await supabase
          .from("show_sponsors")
          .update({
            placement_order: sponsor.placement_order,
            placement_type: sponsor.placement_type,
            mc_anchor_song_id: sponsor.mc_anchor_song_id,
            linked_performer: sponsor.linked_performer,
          })
          .eq("id", sponsor.id)
          .eq("show_id", show.id);

        if (error) {
          throw error;
        }
      }

      setShowSponsors(nextSponsors);
      setMcStatusMessage("Sponsor flow order updated.");
    } catch (error) {
      setMcErrorMessage(getErrorMessage(error));
      await loadShowData(false);
    } finally {
      setActiveSponsorActionId(null);
    }
  }

  async function handleMoveMcSponsorBySong(sponsorReadId: string, direction: "up" | "down") {
    if (!show) {
      setMcErrorMessage("The show is not loaded yet.");
      return;
    }

    const sponsorToMove = mcPlacementSponsors.find((sponsor) => sponsor.id === sponsorReadId);
    const firstSet2SongId = setlist.find((song) => song.section === "set2")?.id ?? null;

    if (
      sponsorToMove &&
      ((sponsorToMove.placement_type === "before_intermission" && direction === "down") ||
        ((sponsorToMove.placement_type === "after_intermission" ||
          (firstSet2SongId &&
            sponsorToMove.placement_type === "before_performer" &&
            sponsorToMove.mc_anchor_song_id === firstSet2SongId)) &&
          direction === "up"))
    ) {
      const nextPlacementType =
        direction === "down" ? "before_performer" : "before_intermission";
      const nextAnchorSongId =
        direction === "down" ? firstSet2SongId : null;

      setMcErrorMessage(null);
      setMcStatusMessage(null);
      setActiveSponsorActionId(`mc-${sponsorReadId}`);

      try {
        const supabase = createClient();
        const { error } = await supabase
          .from("mc_sponsor_reads")
          .update({
            placement_type: nextPlacementType,
            anchor_song_id: nextAnchorSongId,
            linked_performer: null,
          })
          .eq("id", sponsorReadId)
          .eq("show_id", show.id);

        if (error) {
          throw error;
        }

        setMcSponsorReads((currentReads) =>
          currentReads.map((read) =>
            read.id === sponsorReadId
              ? {
                  ...read,
                  placement_type: nextPlacementType,
                  anchor_song_id: nextAnchorSongId,
                  linked_performer: null,
                }
              : read,
          ),
        );
        setMcStatusMessage("Sponsor flow order updated.");
      } catch (error) {
        setMcErrorMessage(getErrorMessage(error));
        await loadShowData(false);
      } finally {
        setActiveSponsorActionId(null);
      }

      return;
    }

    const currentIndex = adminMcSponsorPlacementItems.findIndex(
      (item) => item.kind === "sponsor" && item.sponsor.id === sponsorReadId,
    );

    if (currentIndex < 0) {
      return;
    }

    const targetIndex = direction === "up" ? currentIndex - 1 : currentIndex + 1;

    if (targetIndex < 0 || targetIndex >= adminMcSponsorPlacementItems.length) {
      return;
    }

    const currentItem = adminMcSponsorPlacementItems[currentIndex];
    const neighborItem = adminMcSponsorPlacementItems[targetIndex];

    if (!currentItem || currentItem.kind !== "sponsor" || !neighborItem) {
      return;
    }

    const reorderedItems = [...adminMcSponsorPlacementItems];
    [reorderedItems[currentIndex], reorderedItems[targetIndex]] = [
      reorderedItems[targetIndex],
      reorderedItems[currentIndex],
    ];

    const movableSequence = reorderedItems.filter(
      (
        item,
      ): item is
        | Extract<McSponsorPlacementRenderableItem, { kind: "sponsor" }>
        | Extract<McSponsorPlacementRenderableItem, { kind: "segment" }> =>
        item.kind === "sponsor" || item.kind === "segment",
    );

    const movedSponsorPlacement = resolveMcSponsorPlacementFromSongFlow(reorderedItems, sponsorReadId);
    const nextSponsorReads = mcSponsorReads
      .map((read) => {
        const nextOrder = movableSequence.findIndex(
          (item) => item.kind === "sponsor" && item.sponsor.id === read.id,
        );

        if (nextOrder < 0) {
          return read;
        }

        if (read.id === sponsorReadId) {
          return {
            ...read,
            placement_order: nextOrder + 1,
            placement_type: movedSponsorPlacement.placement_type,
            anchor_song_id: movedSponsorPlacement.mc_anchor_song_id,
            linked_performer: movedSponsorPlacement.linked_performer,
          };
        }

        return {
          ...read,
          placement_order: nextOrder + 1,
        };
      })
      .sort((readA, readB) => readA.placement_order - readB.placement_order);

    setMcErrorMessage(null);
    setMcStatusMessage(null);
    setActiveSponsorActionId(`mc-${sponsorReadId}`);

    try {
      const supabase = createClient();

      for (const sponsorRead of nextSponsorReads) {
        const { error } = await supabase
          .from("mc_sponsor_reads")
          .update({
            placement_order: sponsorRead.placement_order,
            placement_type: sponsorRead.placement_type,
            anchor_song_id: sponsorRead.anchor_song_id,
            linked_performer: sponsorRead.linked_performer,
          })
          .eq("id", sponsorRead.id)
          .eq("show_id", show.id);

        if (error) {
          throw error;
        }
      }

      setMcSponsorReads(sortMcSponsorReads(nextSponsorReads));
      setMcStatusMessage("Sponsor flow order updated.");
    } catch (error) {
      setMcErrorMessage(getErrorMessage(error));
      await loadShowData(false);
    } finally {
      setActiveSponsorActionId(null);
    }
  }

  async function handleMoveMcSpecialSegment(segmentId: string, direction: "up" | "down") {
    if (!show) {
      setMcErrorMessage("The show is not loaded yet.");
      return;
    }

    const currentIndex = adminMcSponsorPlacementItems.findIndex(
      (item) => item.kind === "segment" && item.segment.id === segmentId,
    );

    if (currentIndex < 0) {
      return;
    }

    const targetIndex = direction === "up" ? currentIndex - 1 : currentIndex + 1;

    if (targetIndex < 0 || targetIndex >= adminMcSponsorPlacementItems.length) {
      return;
    }

    const currentItem = adminMcSponsorPlacementItems[currentIndex];
    const neighborItem = adminMcSponsorPlacementItems[targetIndex];

    if (!currentItem || currentItem.kind !== "segment" || !neighborItem) {
      return;
    }

    const reorderedItems = [...adminMcSponsorPlacementItems];
    [reorderedItems[currentIndex], reorderedItems[targetIndex]] = [
      reorderedItems[targetIndex],
      reorderedItems[currentIndex],
    ];

    const segmentSequence = reorderedItems.filter(
      (
        item,
      ): item is Extract<McSponsorPlacementRenderableItem, { kind: "segment" }> =>
        item.kind === "segment",
    );

    const movedSegmentPlacement = resolveMcSpecialSegmentPlacementFromSongFlow(
      reorderedItems,
      segmentId,
    );
    const nextSegments = mcSpecialSegments
      .map((segment) => {
        const nextOrder = segmentSequence.findIndex((item) => item.segment.id === segment.id);

        if (nextOrder < 0) {
          return segment;
        }

        if (segment.id === segmentId) {
          return {
            ...segment,
            placement_order: nextOrder + 1,
            placement_type: movedSegmentPlacement.placement_type,
            anchor_song_id: movedSegmentPlacement.anchor_song_id,
            anchor_sponsor_read_id: movedSegmentPlacement.anchor_sponsor_read_id,
          };
        }

        return {
          ...segment,
          placement_order: nextOrder + 1,
        };
      })
      .sort((segmentA, segmentB) => segmentA.placement_order - segmentB.placement_order);

    setMcErrorMessage(null);
    setMcStatusMessage(null);
    setActiveSponsorActionId(`mc-special-segment-move-${segmentId}`);

    try {
      const supabase = createClient();

      for (const segment of nextSegments) {
        const { error } = await supabase
          .from("mc_special_segments")
          .update({
            placement_order: segment.placement_order,
            placement_type: segment.placement_type,
            anchor_song_id: segment.anchor_song_id,
            anchor_sponsor_read_id: segment.anchor_sponsor_read_id,
          })
          .eq("id", segment.id)
          .eq("show_id", show.id);

        if (error) {
          throw error;
        }
      }

      setMcSpecialSegments(nextSegments);
      setMcStatusMessage("Special segment order updated.");
    } catch (error) {
      setMcErrorMessage(getErrorMessage(error));
      await loadShowData(false);
    } finally {
      setActiveSponsorActionId(null);
    }
  }

  async function handleReorderMcPlacementItems(sourceIndex: number, targetIndex: number) {
    if (!show) {
      setMcErrorMessage("The show is not loaded yet.");
      return;
    }

    if (sourceIndex === targetIndex) {
      return;
    }

    const movedItem = adminMcSponsorPlacementItems[sourceIndex];

    if (!movedItem || (movedItem.kind !== "sponsor" && movedItem.kind !== "segment")) {
      return;
    }

    const reorderedItems = [...adminMcSponsorPlacementItems];
    const [removedItem] = reorderedItems.splice(sourceIndex, 1);

    if (!removedItem) {
      return;
    }

    const insertionIndex =
      sourceIndex < targetIndex ? Math.max(targetIndex - 1, 0) : targetIndex;

    reorderedItems.splice(insertionIndex, 0, removedItem);

    const movableSequence = reorderedItems.filter(
      (
        item,
      ): item is
        | Extract<McSponsorPlacementRenderableItem, { kind: "sponsor" }>
        | Extract<McSponsorPlacementRenderableItem, { kind: "segment" }> =>
        item.kind === "sponsor" || item.kind === "segment",
    );

    const nextSponsorReads = mcSponsorReads.map((read) => {
      const nextOrder = movableSequence.findIndex(
        (item) => item.kind === "sponsor" && item.sponsor.id === read.id,
      );

      if (nextOrder < 0) {
        return read;
      }

      if (movedItem.kind === "sponsor" && read.id === movedItem.sponsor.id) {
        const movedSponsorPlacement = resolveMcSponsorPlacementFromSongFlow(
          reorderedItems,
          movedItem.sponsor.id,
        );

        return {
          ...read,
          placement_order: nextOrder + 1,
          placement_type: movedSponsorPlacement.placement_type,
          anchor_song_id: movedSponsorPlacement.mc_anchor_song_id,
          linked_performer: movedSponsorPlacement.linked_performer,
        };
      }

      return {
        ...read,
        placement_order: nextOrder + 1,
      };
    });

    const nextSegments = mcSpecialSegments.map((segment) => {
      const nextOrder = movableSequence.findIndex(
        (item) => item.kind === "segment" && item.segment.id === segment.id,
      );

      if (nextOrder < 0) {
        return segment;
      }

        if (movedItem.kind === "segment" && segment.id === movedItem.segment.id) {
        const movedSegmentPlacement = resolveMcSpecialSegmentPlacementFromSongFlow(
          reorderedItems,
          movedItem.segment.id,
        );

          return {
            ...segment,
            placement_order: nextOrder + 1,
            placement_type: movedSegmentPlacement.placement_type,
            anchor_song_id: movedSegmentPlacement.anchor_song_id,
            anchor_sponsor_read_id: movedSegmentPlacement.anchor_sponsor_read_id,
          };
        }

      return {
        ...segment,
        placement_order: nextOrder + 1,
      };
    });

    setMcErrorMessage(null);
    setMcStatusMessage(null);
    setActiveSponsorActionId(`mc-reorder-${movedItem.kind}-${movedItem.id}`);

    try {
      const supabase = createClient();

      for (const sponsorRead of nextSponsorReads) {
        const { error } = await supabase
          .from("mc_sponsor_reads")
          .update({
            placement_order: sponsorRead.placement_order,
            placement_type: sponsorRead.placement_type,
            anchor_song_id: sponsorRead.anchor_song_id,
            linked_performer: sponsorRead.linked_performer,
          })
          .eq("id", sponsorRead.id)
          .eq("show_id", show.id);

        if (error) {
          throw error;
        }
      }

      for (const segment of nextSegments) {
        const { error } = await supabase
          .from("mc_special_segments")
          .update({
            placement_order: segment.placement_order,
            placement_type: segment.placement_type,
            anchor_song_id: segment.anchor_song_id,
            anchor_sponsor_read_id: segment.anchor_sponsor_read_id,
          })
          .eq("id", segment.id)
          .eq("show_id", show.id);

        if (error) {
          throw error;
        }
      }

      setMcSponsorReads(sortMcSponsorReads(nextSponsorReads));
      setMcSpecialSegments(nextSegments);
      setMcStatusMessage("MC running order updated.");
    } catch (error) {
      setMcErrorMessage(getErrorMessage(error));
      await loadShowData(false);
    } finally {
      setActiveSponsorActionId(null);
    }
  }

