  async function handleCopyGuestSongsLink() {
    if (!show?.slug) {
      setActionError("Guest songs link is not available until this show has a valid slug.");
      return;
    }

    try {
      await navigator.clipboard.writeText(buildGuestSongsUrl(show.slug));
      setActionError(null);
      setCopiedGuestSongsLink(true);

      window.setTimeout(() => {
        setCopiedGuestSongsLink(false);
      }, 1800);
    } catch (error) {
      setActionError(getErrorMessage(error));
    }
  }

  function handleOpenGuestSongsLink() {
    if (!show?.slug) {
      setActionError("Guest songs link is not available until this show has a valid slug.");
      return;
    }

    if (typeof window === "undefined") {
      return;
    }

    window.open(buildGuestSongsUrl(show.slug), "_blank", "noopener,noreferrer");
  }

  async function handleCopyRehearsalLink() {
    if (!show?.slug) {
      setRehearsalErrorMessage("Rehearsal link is not available until this show has a valid slug.");
      return;
    }

    try {
      const rehearsalUrl =
        typeof window !== "undefined"
          ? `${window.location.origin}/band/${encodeURIComponent(show.slug)}?tab=rehearsal`
          : buildBandRehearsalUrl(show.slug);

      await navigator.clipboard.writeText(rehearsalUrl);
      setRehearsalErrorMessage(null);
      setCopiedRehearsalLink(true);

      window.setTimeout(() => {
        setCopiedRehearsalLink(false);
      }, 1800);
    } catch (error) {
      setRehearsalErrorMessage(getErrorMessage(error));
    }
  }

