  async function handleAddManualRehearsalSongToLibrary(entry: RehearsalEntryWithSong) {
    if (!show) {
      setRehearsalErrorMessage("The show is not loaded yet.");
      return;
    }

    if (entry.is_library_linked) {
      setRehearsalErrorMessage("This rehearsal song is already linked to the song library.");
      return;
    }

    const rehearsalTitle = (rehearsalTitleDrafts[entry.id] ?? entry.title).trim();
    const rehearsalKey = normalizeOptionalField(rehearsalKeyDrafts[entry.id] ?? entry.song_key ?? "");
    const rehearsalSungBy = normalizeOptionalField(rehearsalSungByDrafts[entry.id] ?? entry.sung_by ?? "");
    const rehearsalNotes = normalizeOptionalField(rehearsalNoteDrafts[entry.id] ?? entry.notes ?? "");

    if (!rehearsalTitle) {
      setRehearsalErrorMessage("Enter a song title before adding this rehearsal entry to the library.");
      return;
    }

    setActiveRehearsalActionId(`library-${entry.id}`);
    setRehearsalErrorMessage(null);
    setRehearsalStatusMessage(null);

    try {
      const normalizedTitle = rehearsalTitle.toLowerCase();
      const existingLibrarySong = songLibrary.find(
        (song) => song.title.trim().toLowerCase() === normalizedTitle,
      );
      const supabase = createClient();

      let linkedSong = existingLibrarySong ?? null;

      if (!linkedSong) {
        const createdByRole = hasAdminPortalAccess ? "admin" : "band";
        const { data: createdSong, error: createSongError } = await supabase
          .from("songs")
          .insert({
            title: rehearsalTitle,
            key: rehearsalKey,
            sung_by: rehearsalSungBy,
            notes: rehearsalNotes,
            created_by_role: createdByRole,
            created_by_name: null,
          })
          .select("*")
          .single();

        if (createSongError) {
          throw createSongError;
        }

        linkedSong = normalizeSongLibrarySong(createdSong as SongLibrarySong);
      }

      const ensuredLinkedSong = linkedSong;

      if (!existingLibrarySong) {
        setSongLibrary((currentSongs) =>
          [...currentSongs, ensuredLinkedSong].sort((songA, songB) => songA.title.localeCompare(songB.title)),
        );
      }

      const { data: updatedEntry, error: updateEntryError } = await supabase
        .from("rehearsal_entries")
        .update({
          song_id: ensuredLinkedSong.id,
          custom_title: null,
        })
        .eq("id", entry.id)
        .select(`
          *,
          library_song:song_id (
            id,
            title,
            key,
            sung_by,
            tempo,
            song_type,
            notes,
            lyrics,
            created_by_role,
            created_by_name,
            created_at
          )
        `)
        .single();

      if (updateEntryError) {
        throw updateEntryError;
      }

      const normalizedEntry = normalizeRehearsalEntry(updatedEntry as RehearsalEntryRow);
      setRehearsalEntries((currentEntries) =>
        sortRehearsalEntries(
          currentEntries.map((currentEntry) =>
            currentEntry.id === entry.id ? normalizedEntry : currentEntry,
          ),
        ),
      );
      setRehearsalTitleDrafts((currentDrafts) => ({
        ...currentDrafts,
        [normalizedEntry.id]: normalizedEntry.title,
      }));
      setRehearsalKeyDrafts((currentDrafts) => ({
        ...currentDrafts,
        [normalizedEntry.id]: normalizedEntry.song_key ?? "",
      }));
      setRehearsalSungByDrafts((currentDrafts) => ({
        ...currentDrafts,
        [normalizedEntry.id]: normalizedEntry.sung_by ?? "",
      }));
      setRehearsalStatusMessage(
        existingLibrarySong
          ? `"${normalizedEntry.title}" was linked to the existing Song Library entry.`
          : `"${normalizedEntry.title}" was added to the Song Library and linked to rehearsal.`,
      );
    } catch (error) {
      setRehearsalErrorMessage(getErrorMessage(error));
    } finally {
      setActiveRehearsalActionId(null);
    }
  }

  async function handleDeleteRehearsalEntry(entry: RehearsalEntryWithSong) {
    const shouldDelete = window.confirm(`Remove "${entry.title}" from this rehearsal list?`);

    if (!shouldDelete) {
      return;
    }

    setActiveRehearsalActionId(entry.id);
    setRehearsalErrorMessage(null);
    setRehearsalStatusMessage(null);

    try {
      const linkedRecordings = rehearsalRecordings.filter(
        (recording) => recording.rehearsal_entry_id === entry.id,
      );
      const supabase = createClient();
      const { error } = await supabase.from("rehearsal_entries").delete().eq("id", entry.id);

      if (error) {
        throw error;
      }

      await Promise.all(
        linkedRecordings.map((recording) => deleteRehearsalRecordingFile(recording.file_path)),
      );

      setRehearsalEntries((currentEntries) =>
        currentEntries.filter((currentEntry) => currentEntry.id !== entry.id),
      );
      setRehearsalRecordings((currentRecordings) =>
        currentRecordings.filter((recording) => recording.rehearsal_entry_id !== entry.id),
      );
      setRehearsalNoteDrafts((currentDrafts) => {
        const nextDrafts = { ...currentDrafts };
        delete nextDrafts[entry.id];
        return nextDrafts;
      });
      setRehearsalTitleDrafts((currentDrafts) => {
        const nextDrafts = { ...currentDrafts };
        delete nextDrafts[entry.id];
        return nextDrafts;
      });
      setRehearsalKeyDrafts((currentDrafts) => {
        const nextDrafts = { ...currentDrafts };
        delete nextDrafts[entry.id];
        return nextDrafts;
      });
      setRehearsalSungByDrafts((currentDrafts) => {
        const nextDrafts = { ...currentDrafts };
        delete nextDrafts[entry.id];
        return nextDrafts;
      });
      setOpenRehearsalEntryIds((currentState) => {
        const nextState = { ...currentState };
        delete nextState[entry.id];
        return nextState;
      });
      setRehearsalStatusMessage(`Removed "${entry.title}" from rehearsal.`);
    } catch (error) {
      setRehearsalErrorMessage(getErrorMessage(error));
    } finally {
      setActiveRehearsalActionId(null);
    }
  }

  async function handleMoveRehearsalEntry(
    entry: RehearsalEntryWithSong,
    direction: "up" | "down",
  ) {
    const sectionEntries = sortRehearsalEntries(rehearsalEntries).filter(
      (currentEntry) =>
        normalizeRehearsalSectionLabel(currentEntry.section_label) ===
        normalizeRehearsalSectionLabel(entry.section_label),
    );
    const currentIndex = sectionEntries.findIndex((currentEntry) => currentEntry.id === entry.id);

    if (currentIndex === -1) {
      return;
    }

    const targetIndex = direction === "up" ? currentIndex - 1 : currentIndex + 1;
    const neighbor = sectionEntries[targetIndex];

    if (!neighbor) {
      return;
    }

    setActiveRehearsalActionId(`move-${entry.id}`);
    setRehearsalErrorMessage(null);
    setRehearsalStatusMessage(null);

    try {
      const supabase = createClient();
      const { error: currentError } = await supabase
        .from("rehearsal_entries")
        .update({ sort_order: neighbor.sort_order })
        .eq("id", entry.id);

      if (currentError) {
        throw currentError;
      }

      const { error: neighborError } = await supabase
        .from("rehearsal_entries")
        .update({ sort_order: entry.sort_order })
        .eq("id", neighbor.id);

      if (neighborError) {
        throw neighborError;
      }

      setRehearsalEntries((currentEntries) =>
        sortRehearsalEntries(
          currentEntries.map((currentEntry) => {
            if (currentEntry.id === entry.id) {
              return { ...currentEntry, sort_order: neighbor.sort_order };
            }

            if (currentEntry.id === neighbor.id) {
              return { ...currentEntry, sort_order: entry.sort_order };
            }

            return currentEntry;
          }),
        ),
      );
    } catch (error) {
      setRehearsalErrorMessage(getErrorMessage(error));
    } finally {
      setActiveRehearsalActionId(null);
    }
  }

  async function handleUploadRehearsalRecording(entry: RehearsalEntryWithSong) {
    if (!show?.slug || !show?.id) {
      setRehearsalErrorMessage("The show is not ready for uploads yet.");
      return;
    }

    const file = rehearsalRecordingFiles[entry.id] ?? null;
    const validationError = validateSongMp3File(file);

    if (validationError) {
      setRehearsalErrorMessage(validationError);
      return;
    }

    if (!file) {
      setRehearsalErrorMessage("Choose an MP3 or M4A recording first.");
      return;
    }

    setActiveRehearsalActionId(`upload-${entry.id}`);
    setRehearsalErrorMessage(null);
    setRehearsalStatusMessage(null);

    try {
      const uploadedRecording = await uploadRehearsalRecordingFile({
        file,
        showSlug: show.slug,
        rehearsalEntryId: entry.id,
      });
      const supabase = createClient();
      const { data, error } = await supabase
        .from("rehearsal_recordings")
        .insert({
          show_id: show.id,
          rehearsal_entry_id: entry.id,
          file_name: uploadedRecording.file_name,
          file_path: uploadedRecording.file_path,
          file_url: uploadedRecording.file_url,
        })
        .select("*")
        .single();

      if (error) {
        await deleteRehearsalRecordingFile(uploadedRecording.file_path);
        throw error;
      }

      setRehearsalRecordings((currentRecordings) =>
        sortRehearsalRecordings([
          normalizeRehearsalRecording(data as RehearsalRecording),
          ...currentRecordings,
        ]),
      );
      resetRehearsalRecordingInput(entry.id);
      setRehearsalStatusMessage(`Uploaded rehearsal recording for "${entry.title}".`);
    } catch (error) {
      setRehearsalErrorMessage(getErrorMessage(error));
    } finally {
      setActiveRehearsalActionId(null);
    }
  }

  async function handleDeleteRehearsalRecording(recording: RehearsalRecording) {
    const shouldDelete = window.confirm(`Delete rehearsal recording "${recording.file_name}"?`);

    if (!shouldDelete) {
      return;
    }

    setActiveRehearsalActionId(`recording-${recording.id}`);
    setRehearsalErrorMessage(null);
    setRehearsalStatusMessage(null);

    try {
      const supabase = createClient();
      const { error } = await supabase.from("rehearsal_recordings").delete().eq("id", recording.id);

      if (error) {
        throw error;
      }

      await deleteRehearsalRecordingFile(recording.file_path);
      setRehearsalRecordings((currentRecordings) =>
        currentRecordings.filter((currentRecording) => currentRecording.id !== recording.id),
      );
      setRehearsalStatusMessage(`Deleted rehearsal recording "${recording.file_name}".`);
    } catch (error) {
      setRehearsalErrorMessage(getErrorMessage(error));
    } finally {
      setActiveRehearsalActionId(null);
    }
  }

  async function handleToggleRehearsalPreviewAudio(audioUrl: string, audioKey: string) {
    const currentAudio = rehearsalPreviewAudioRef.current;

    if (currentAudio && activeRehearsalPreviewAudioKey === audioKey) {
      currentAudio.pause();
      rehearsalPreviewAudioRef.current = null;
      setActiveRehearsalPreviewAudioKey(null);
      return;
    }

    if (currentAudio) {
      currentAudio.pause();
    }

    const previewAudio = new Audio(audioUrl);
    rehearsalPreviewAudioRef.current = previewAudio;
    setActiveRehearsalPreviewAudioKey(audioKey);

    previewAudio.addEventListener("ended", () => {
      if (rehearsalPreviewAudioRef.current === previewAudio) {
        rehearsalPreviewAudioRef.current = null;
        setActiveRehearsalPreviewAudioKey(null);
      }
    });

    try {
      await previewAudio.play();
    } catch (error) {
      if (rehearsalPreviewAudioRef.current === previewAudio) {
        rehearsalPreviewAudioRef.current = null;
        setActiveRehearsalPreviewAudioKey(null);
      }

      setRehearsalErrorMessage(getErrorMessage(error));
    }
  }

  async function handleSyncRehearsalToSetlist() {
    if (!show) {
      setRehearsalErrorMessage("The show is not loaded yet.");
      return;
    }

    setActiveRehearsalActionId("sync-setlist");
    setRehearsalErrorMessage(null);
    setRehearsalStatusMessage(null);

    try {
      const supabase = createClient();
      const createdByRole = hasAdminPortalAccess ? "admin" : "band";
      let nextSongLibrary = [...songLibrary];
      let nextRehearsalEntries = [...rehearsalEntries];
      const rehearsalEntriesById = new Map(nextRehearsalEntries.map((entry) => [entry.id, entry] as const));
      const orderedRehearsalEntries = [...rehearsalEntries].sort((entryA, entryB) => {
        const getSectionSortOrder = (sectionLabel: string | null | undefined) => {
          if (sectionLabel === "set1") {
            return 0;
          }

          if (sectionLabel === "set2") {
            return 1;
          }

          return 2;
        };

        const sectionDifference =
          getSectionSortOrder(entryA.section_label) - getSectionSortOrder(entryB.section_label);

        if (sectionDifference !== 0) {
          return sectionDifference;
        }

        if (entryA.sort_order !== entryB.sort_order) {
          return entryA.sort_order - entryB.sort_order;
        }

        return entryA.created_at.localeCompare(entryB.created_at);
      });

      const syncedTargets: Array<{
        rehearsalEntryId: string;
        songId: string;
        section: SetSection;
        title: string;
        key: string | null;
        sungBy: string | null;
        tempo: SongTempo | null;
        songType: SongType | null;
        notes: string | null;
        lyrics: string | null;
        librarySong: SongLibrarySong | null;
      }> = [];
      const seenSongIds = new Set<string>();
      let skippedCount = 0;

      for (const sourceEntry of orderedRehearsalEntries) {
        let workingEntry = rehearsalEntriesById.get(sourceEntry.id) ?? sourceEntry;
        let workingSongId = workingEntry.song_id;
        let linkedLibrarySong = workingSongId
          ? nextSongLibrary.find((song) => song.id === workingSongId) ?? null
          : null;

        if (!workingSongId) {
          const manualTitle =
            workingEntry.custom_title?.trim() ||
            rehearsalTitleDrafts[workingEntry.id]?.trim() ||
            workingEntry.title.trim();

          if (!manualTitle) {
            skippedCount += 1;
            continue;
          }

          const { data: createdSong, error: createSongError } = await supabase
            .from("songs")
            .insert({
              title: manualTitle,
              key: workingEntry.song_key ?? null,
              sung_by: workingEntry.sung_by ?? null,
              notes: workingEntry.notes ?? null,
              created_by_role: createdByRole,
              created_by_name: null,
            })
            .select("*")
            .single();

          if (createSongError) {
            throw createSongError;
          }

          linkedLibrarySong = normalizeSongLibrarySong(createdSong as SongLibrarySong);
          nextSongLibrary = [...nextSongLibrary, linkedLibrarySong].sort((songA, songB) =>
            songA.title.localeCompare(songB.title),
          );

          const { data: updatedEntry, error: updateEntryError } = await supabase
            .from("rehearsal_entries")
            .update({
              song_id: linkedLibrarySong.id,
              custom_title: null,
            })
            .eq("id", workingEntry.id)
            .select(`
              *,
              library_song:song_id (
                id,
                title,
                key,
                sung_by,
                tempo,
                song_type,
                notes,
                lyrics,
                created_by_role,
                created_by_name,
                created_at
              )
            `)
            .single();

          if (updateEntryError) {
            throw updateEntryError;
          }

          workingEntry = normalizeRehearsalEntry(updatedEntry as RehearsalEntryRow);
          workingSongId = workingEntry.song_id;
          nextRehearsalEntries = sortRehearsalEntries(
            nextRehearsalEntries.map((entry) =>
              entry.id === workingEntry.id ? workingEntry : entry,
            ),
          );
          rehearsalEntriesById.set(workingEntry.id, workingEntry);
        }

        if (!workingSongId) {
          skippedCount += 1;
          continue;
        }

        const rehearsalLeadVocal = workingEntry.sung_by?.trim() ?? "";
        const linkedLibraryLeadVocal = linkedLibrarySong?.sung_by?.trim() ?? "";

        if (linkedLibrarySong && rehearsalLeadVocal && !linkedLibraryLeadVocal) {
          const { data: updatedSong, error: updateSongError } = await supabase
            .from("songs")
            .update({
              sung_by: rehearsalLeadVocal,
            })
            .eq("id", linkedLibrarySong.id)
            .select("*")
            .single();

          if (updateSongError) {
            throw updateSongError;
          }

          linkedLibrarySong = normalizeSongLibrarySong(updatedSong as SongLibrarySong);
          nextSongLibrary = nextSongLibrary.map((song) =>
            song.id === linkedLibrarySong?.id ? linkedLibrarySong : song,
          );
        }

        if (seenSongIds.has(workingSongId)) {
          skippedCount += 1;
          continue;
        }

        seenSongIds.add(workingSongId);
        syncedTargets.push({
          rehearsalEntryId: workingEntry.id,
          songId: workingSongId,
          section: workingEntry.section_label === "set1"
            ? "set1"
            : workingEntry.section_label === "set2"
              ? "set2"
              : "encore",
          title: workingEntry.title,
          key: workingEntry.song_key ?? null,
          sungBy: workingEntry.sung_by ?? null,
          tempo: workingEntry.tempo ?? null,
          songType: workingEntry.song_type ?? null,
          notes: workingEntry.notes ?? null,
          lyrics: linkedLibrarySong?.lyrics ?? null,
          librarySong: linkedLibrarySong,
        });
      }

      let workingSetlist = sortSetlistSongs([...setlist]);
      const existingSetlistBySongId = new Map<string, SetlistSong>();

      for (const setlistSong of workingSetlist) {
        if (setlistSong.song_id && !existingSetlistBySongId.has(setlistSong.song_id)) {
          existingSetlistBySongId.set(setlistSong.song_id, setlistSong);
        }
      }

      const syncedResolvedSongs: SetlistSong[] = [];
      let addedCount = 0;

      for (const target of syncedTargets) {
        const existingSetlistSong = existingSetlistBySongId.get(target.songId);

        if (existingSetlistSong) {
          syncedResolvedSongs.push({
            ...existingSetlistSong,
            section: target.section,
            set_section: target.section,
          });
          continue;
        }

        const provisionalPosition = getNextPositionForSection(workingSetlist, target.section);
        const { data: insertedSetlistEntry, error: insertSetlistError } = await supabase
          .from("setlist_entries")
          .insert({
            show_id: show.id,
            section: target.section,
            position: provisionalPosition,
            source_type: "library",
            song_id: target.songId,
          })
          .select("*")
          .single();

        if (insertSetlistError) {
          throw insertSetlistError;
        }

        const normalizedSetlistSong = normalizeSetlistSong({
          ...(insertedSetlistEntry as SetlistEntryQueryRow),
          title: target.title,
          key: target.key,
          tempo: target.tempo,
          song_type: target.songType,
          notes: target.notes,
          lyrics: target.lyrics,
          library_song: target.librarySong,
        });

        workingSetlist = sortSetlistSongs([...workingSetlist, normalizedSetlistSong]);
        existingSetlistBySongId.set(target.songId, normalizedSetlistSong);
        syncedResolvedSongs.push(normalizedSetlistSong);
        addedCount += 1;
      }

      const syncedSetlistEntryIds = new Set(syncedResolvedSongs.map((song) => song.id));
      const unsyncedSongs = sortSetlistSongs(
        workingSetlist.filter((song) => !syncedSetlistEntryIds.has(song.id)),
      );
      const syncedSongsBySection = new Map<SetSection, SetlistSong[]>(
        setlistSectionOrder.map((section) => [section, []]),
      );

      for (const syncedSong of syncedResolvedSongs) {
        syncedSongsBySection.get(syncedSong.section)?.push(syncedSong);
      }

      const finalSetlist: SetlistSong[] = [];

      for (const section of setlistSectionOrder) {
        const orderedSectionSongs = [
          ...(syncedSongsBySection.get(section) ?? []),
          ...unsyncedSongs.filter((song) => song.section === section),
        ];

        orderedSectionSongs.forEach((song, index) => {
          finalSetlist.push({
            ...song,
            section,
            set_section: section,
            position: index + 1,
          });
        });
      }

      const originalSetlistById = new Map(workingSetlist.map((song) => [song.id, song] as const));
      let updatedCount = 0;

      for (const finalSong of finalSetlist) {
        const originalSong = originalSetlistById.get(finalSong.id);

        if (!originalSong) {
          continue;
        }

        if (originalSong.section === finalSong.section && originalSong.position === finalSong.position) {
          continue;
        }

        const { error: updateSetlistError } = await supabase
          .from("setlist_entries")
          .update({
            section: finalSong.section,
            position: finalSong.position,
          })
          .eq("id", finalSong.id);

        if (updateSetlistError) {
          throw updateSetlistError;
        }

        updatedCount += 1;
      }

      setSongLibrary(nextSongLibrary);
      setRehearsalEntries(nextRehearsalEntries);
      setRehearsalTitleDrafts((currentDrafts) =>
        nextRehearsalEntries.reduce<Record<string, string>>((lookup, entry) => {
          lookup[entry.id] = currentDrafts[entry.id] ?? entry.title;
          return lookup;
        }, {}),
      );
      setRehearsalKeyDrafts((currentDrafts) =>
        nextRehearsalEntries.reduce<Record<string, string>>((lookup, entry) => {
          lookup[entry.id] = currentDrafts[entry.id] ?? entry.song_key ?? "";
          return lookup;
        }, {}),
      );
      setRehearsalSungByDrafts((currentDrafts) =>
        nextRehearsalEntries.reduce<Record<string, string>>((lookup, entry) => {
          lookup[entry.id] = currentDrafts[entry.id] ?? entry.sung_by ?? "";
          return lookup;
        }, {}),
      );
      setSetlist(sortSetlistSongs(finalSetlist));
      setRehearsalStatusMessage(
        `Synced setlist: Added ${addedCount}, updated ${updatedCount}, skipped ${skippedCount}.`,
      );
    } catch (error) {
      setRehearsalErrorMessage(getErrorMessage(error));
      await loadShowData(false);
    } finally {
      setActiveRehearsalActionId(null);
    }
  }

  function handlePrintRehearsalSheet(printMode: "all" | "set1" | "set2") {
    if (!show) {
      setRehearsalErrorMessage("The show is not loaded yet.");
      return;
    }

    const printWindow = window.open("", "_blank");

    if (!printWindow) {
      window.alert("The print window was blocked. Please allow pop-ups and try again.");
      return;
    }

    const printHtml = buildRehearsalSheetPrintHtml({
      showName: show.name,
      showDate: show.show_date,
      printMode,
      entries: rehearsalEntries
        .filter((entry) => {
          const normalizedSection = normalizeRehearsalSectionLabel(entry.section_label);
          if (printMode === "set1") {
            return normalizedSection === "set1";
          }
          if (printMode === "set2") {
            return normalizedSection === "set2";
          }
          return true;
        })
        .map((entry) => ({
        title: entry.is_library_linked
          ? entry.title
          : (rehearsalTitleDrafts[entry.id] ?? entry.title).trim() || entry.title,
        notes: rehearsalNoteDrafts[entry.id] ?? entry.notes ?? null,
        sectionLabel: entry.section_label ?? null,
        artist: entry.artist,
        sungBy: rehearsalSungByDrafts[entry.id] ?? entry.sung_by ?? null,
        songKey: entry.song_key,
        tempo: entry.tempo,
        songType: entry.song_type,
        isLibraryLinked: entry.is_library_linked,
      })),
    });

    const triggerPrint = () => {
      if (printWindow.closed) {
        return;
      }

      printWindow.focus();
      printWindow.print();
    };

    printWindow.onload = triggerPrint;
    printWindow.onafterprint = () => {
      printWindow.close();
    };

    const { document } = printWindow;
    document.open();
    document.write(printHtml);
    document.close();

    if (document.readyState === "complete") {
      triggerPrint();
    }
  }

  async function handleCopyGuestProfileLink(profile: GuestProfile) {
    try {
      const guestIdentifier = profile.guest_token ?? profile.id;
      const guestUrl =
        typeof window === "undefined"
          ? `/guest/${guestIdentifier}`
          : `${window.location.origin}/guest/${guestIdentifier}`;

      await navigator.clipboard.writeText(guestUrl);
      setActionError(null);
      setCopiedGuestProfileLinkId(profile.id);

      window.setTimeout(() => {
        setCopiedGuestProfileLinkId((currentProfileId) =>
          currentProfileId === profile.id ? null : currentProfileId,
        );
      }, 1800);
    } catch (error) {
      setActionError(getErrorMessage(error));
    }
  }

